insert into public.catalog_heritages (id, ancestry_id, is_versatile, name_pt, name_en, name_es, description_pt, description_en, description_es, prerequisite, traits, rarity, ruleset, source_book, source_page, data)
values
  ('heritage.ancestry.human.humano_versatil_talento_geral_extra', 'ancestry.human', FALSE, 'Humano Versátil (Talento Geral extra)', 'Versatile Human', 'Humano versátil', 'A capacidade de adaptação da humanidade permite que você aprenda rapidamente diversas especialidades. Você recebe um talento geral de 1º nível adicional para o qual cumpra os pré-requisitos.', 'Humanity''s versatility and drive allows you to master diverse disciplines. You gain a 1st-level general feat for which you meet the prerequisites.', 'La adaptabilidad de la humanidad te permite aprender rápidamente diversas disciplinas. Obtienes una dote general de 1.er nivel para la que cumplas los prerrequisitos.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 44, '{"grants":{"type":"feat","slotId":"1_general_feat","filterType":"Geral","label":{"pt-BR":"Talento Geral (Humano Versátil)","en":"General Feat (Versatile Human)","es":"Dote general (Humano versátil)"}},"needs_review":false}'::jsonb),
  ('heritage.ancestry.human.humano_habilidoso_pericia_extra', 'ancestry.human', FALSE, 'Humano Habilidoso (Perícia extra)', 'Skilled Human', 'Humano habilidoso', 'Sua engenhosidade e curiosidade o tornam proficiente em diversas artes. Você se torna treinado em uma perícia à sua escolha no 1º nível, e treinado em outra perícia adicional no 5º nível.', 'Your ingenuity and varied upbringing make you proficient in multiple fields. You become trained in one skill of your choice at 1st level, and trained in another skill at 5th level.', 'Tu ingenio y crianza variada te hacen competente en múltiples campos. Quedas entrenado en una habilidad de tu elección a nivel 1 y en otra habilidad adicional a nivel 5.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.human.meio_elfo_aelfin', 'ancestry.human', FALSE, 'Meio-Elfo (Aelfin)', 'Half-Elf (Aiphan)', 'Medio elfo (Aelfin)', 'Você descende de humanos e elfos, combinando a graça feérica com a determinação humana. Você recebe visão na penumbra e o traço Elfo, obtendo acesso a talentos de ancestralidade de elfos e meio-elfos.', 'You have heritage from both humans and elves, blending fey grace with human ambition. You gain low-light vision and the Elf trait, gaining access to elf and half-elf ancestry feats.', 'Desciendes de humanos y elfos, combinando la gracia feérica con la ambición humana. Obtienes visión en la penumbra y el rasgo Elfo, accediendo a dotes ancestrales de elfo y medio elfo.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.human.meio_orc_dromaar', 'ancestry.human', FALSE, 'Meio-Orc (Dromaar)', 'Half-Orc (Dromaar)', 'Medio orco (Dromaar)', 'Você carrega sangue humano e orc, demonstrando tenacidade física incomparável. Você recebe visão na penumbra e o traço Orc, obtendo acesso a talentos de ancestralidade de orcs e meio-orcs.', 'You carry the blood of both humans and orcs, displaying remarkable tenacity. You gain low-light vision and the Orc trait, gaining access to orc and half-orc ancestry feats.', 'Llevas sangre de humanos y orcos, demostrando una tenacidad física asombrosa. Obtienes visión en la penumbra y el rasgo Orco, accediendo a dotes ancestrales de orco y medio orco.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.human.humano_herdeiro_do_inverno', 'ancestry.human', FALSE, 'Humano Herdeiro do Inverno', 'Wintertouched Human', 'Humano tocado por el invierno', 'Você possui sangue das terras gélidas ou dos espíritos do inverno em suas veias. Você recebe resistência a frio igual à metade do seu nível (mínimo 1) e trata frio ambiental como um grau menos severo.', 'You have blood of northern frost or winter fey in your lineage. You gain cold resistance equal to half your level (minimum 1) and treat cold environmental effects as one step less severe.', 'Llevas sangre de las tierras gélidas en tus venas. Obtienes resistencia al frío igual a la mitad de tu nivel (mínimo 1) y tratas los efectos ambientales de frío como un paso menos severos.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.dwarf.anao_forjado_em_rocha', 'ancestry.dwarf', FALSE, 'Anão Forjado em Rocha', 'Rock Dwarf', 'Enano forjado en roca', 'Sua sólida conexão com a terra torna você quase inamovível. Você recebe +2 de bônus circunstancial na CD de Fortitude ou Reflexos contra Empurrar ou Derrubar, e ignora 1,5m de movimento forçado.', 'Your solid connection to the subterranean rock makes you unyielding. You gain a +2 circumstance bonus to Fortitude/Reflex DC against Shove or Trip, and reduce forced movement by 5 feet.', 'Tu sólida conexión con la tierra te hace casi inamovible. Obtienes un bonificador circunstancial de +2 a la CD de Fortaleza o Reflejos contra Empujar o Derribar, e ignoras 1,5 m de movimiento forzado.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.dwarf.anao_couro_de_pedra', 'ancestry.dwarf', FALSE, 'Anão Couro-de-Pedra', 'Strong-Blooded Dwarf', 'Enano de sangre fuerte', 'Seu organismo ancestral neutraliza toxinas subterrâneas com extrema eficácia. Você recebe resistência a veneno igual à metade do seu nível (mínimo 1) e cada sucesso em teste de resistência contra venenos reduz o estágio em 2.', 'Your blood resists subterranean and noxious toxins. You gain poison resistance equal to half your level (minimum 1), and each success on a save against poison reduces the stage by 2.', 'Tu sangre ancestral resiste toxinas subterráneas. Obtienes resistencia al veneno igual a la mitad de tu nivel (mínimo 1) y cada éxito al salvarte contra veneno reduce el estadio en 2.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.dwarf.anao_mente_forte', 'ancestry.dwarf', FALSE, 'Anão Mente Forte', 'Strong-Minded Dwarf', 'Enano de mente fuerte', 'Sua determinação inabalável protege seus pensamentos. Sempre que obtiver um sucesso em teste de Vontade contra efeitos mentais ou de medo, você obtém um sucesso decisivo.', 'Your stubborn resolve shields your mind. Whenever you roll a success on a Will save against an emotion or mental effect, you get a critical success instead.', 'Tu terquedad inquebrantable protege tu mente. Siempre que obtengas un éxito en una tirada de Voluntad contra efectos mentales o de miedo, obtienes un éxito crítico.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.dwarf.anao_da_forja', 'ancestry.dwarf', FALSE, 'Anão da Forja', 'Forge Dwarf', 'Enano de la forja', 'Adaptado às temperaturas extremas das profundezas e forjas vulcânicas, você recebe resistência a fogo igual à metade do seu nível (mínimo 1) e trata calor ambiental como um grau menos severo.', 'Acclimated to intense heat and volcanic forges, you gain fire resistance equal to half your level (minimum 1) and treat environmental heat as one step less severe.', 'Adaptado al calor de las forjas volcánicas, obtienes resistencia al fuego igual a la mitad de tu nivel (mínimo 1) y tratas el calor ambiental como un paso menos severo.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.dwarf.anao_da_tumba', 'ancestry.dwarf', FALSE, 'Anão da Tumba', 'Death Warden Dwarf', 'Enano guardián de la muerte', 'Consagrado aos ancestrais que guardam as tumbas eternas, você recebe resistência a dano de Vazio (energia negativa) igual à metade do seu nível e +1 circunstancial em salvamentos contra mortos-vivos.', 'Consecrated to ancestors guarding ancient crypts, you gain void resistance equal to half your level and a +1 circumstance bonus to saves against undead abilities and necromantic effects.', 'Consagrado a los ancestros que custodian criptas antiguas, obtienes resistencia al daño de Vacío igual a la mitad de tu nivel y un bonificador circunstancial de +1 contra efectos de no muertos.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.elf.elfo_da_floresta_antiga', 'ancestry.elf', FALSE, 'Elfo da Floresta Antiga', 'Ancient Elf', 'Elfo anciano', 'Sua longa vivência e estudos ao longo de séculos permitiram dominar outra vocação. Você recebe um talento de dedicação de arquétipo multiclasse de 1º nível, mesmo que sua classe ainda não conceda talentos de arquétipo.', 'Centuries of study and experience give you versatility in another vocation. You gain a 1st-level multiclass archetype dedication feat of your choice.', 'Siglos de estudio y experiencia te permiten dominar otra vocación. Obtienes una dote de dedicación de arquetipo multiclase de 1.er nivel de tu elección.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 52, '{"grants":{"type":"archetype","slotId":"1_archetype_feat","filterType":"Dedicação","label":{"pt-BR":"Dedicação de Arquétipo (Elfo Ancestral)","en":"Archetype Dedication (Ancient Elf)","es":"Dedicación de arquetipo (Elfo anciano)"}},"needs_review":false}'::jsonb),
  ('heritage.ancestry.elf.elfo_do_artico', 'ancestry.elf', FALSE, 'Elfo do Ártico', 'Arctic Elf', 'Elfo ártico', 'Sua linhagem floresceu nos confins gelados do mundo. Você recebe resistência a frio igual à metade do seu nível (mínimo 1) e trata frio severo como apenas frio moderado.', 'Your people adapted to freezing tundra and glacial heights. You gain cold resistance equal to half your level (minimum 1) and treat cold environments as one step less severe.', 'Tu pueblo floreció en tundras heladas. Obtienes resistencia al frío igual a la mitad de tu nivel (mínimo 1) y tratas el frío ambiental como un paso menos severo.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 52, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.elf.elfo_da_caverna', 'ancestry.elf', FALSE, 'Elfo da Caverna', 'Cavern Elf', 'Elfo de las cavernas', 'Nascido nas galerias subterrâneas e fendas escuras, seus olhos se adaptaram à escuridão total. Você recebe visão no escuro em vez de visão na penumbra.', 'Born in deep subterranean vaults and shadowy tunnels, your vision pierces total darkness. You gain darkvision instead of low-light vision.', 'Nacido en bóvedas subterráneas, tus ojos se han adaptado a la oscuridad absoluta. Obtienes visión en la oscuridad en lugar de visión en la penumbra.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 52, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.elf.elfo_vidente', 'ancestry.elf', FALSE, 'Elfo Vidente', 'Seer Elf', 'Elfo vidente', 'Você possui uma sensibilidade inata às correntes mágicas do universo. Você pode conjurar detectar magia como uma magia inata primal ou arcana à vontade e recebe +1 circunstancial para Identificar Magia.', 'You have an innate sensitivity to magical auras. You can cast the detect magic cantrip as an innate spell at will and gain a +1 circumstance bonus to Identify Magic.', 'Posees una sensibilidad innata hacia la magia. Puedes lanzar el truco detectar magia como conjuro innato a voluntad y obtienes un bonificador circunstancial de +1 a Identificar magia.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 52, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.elf.elfo_nomade_dos_sussurros', 'ancestry.elf', FALSE, 'Elfo Nômade dos Sussurros', 'Whisper Elf', 'Elfo del susurro', 'Suas orelhas alongadas e sentidos apurados captam os menores sons e ruídos. Você recebe +2 de bônus circunstancial em testes de Percepção para Procurar criaturas ouvindo seus movimentos.', 'Your keen elven ears catch the subtlest auditory cues. You gain a +2 circumstance bonus to Perception checks to Seek creatures using hearing.', 'Tus aguzadas orejas captan los sonidos más sutiles. Obtienes un bonificador circunstancial de +2 en pruebas de Percepción para Buscar criaturas mediante el oído.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 52, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.gnome.gnomo_camaleao', 'ancestry.gnome', FALSE, 'Gnomo Camaleão', 'Chameleon Gnome', 'Gnomo camaleón', 'Sua pele e cabelos mudam sutilmente de tom para combinar com o ambiente. Você recebe +2 de bônus circunstancial em Furtividade para Esconder-se em ambientes naturais ou com vegetação.', 'Your coloration shifts subtly to match your surroundings. You gain a +2 circumstance bonus to Stealth checks to Hide in natural or leafy environments.', 'Tu piel y cabello cambian de tono sutilmente. Obtienes un bonificador circunstancial de +2 en Sigilo para Esconderte en entornos naturales.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 56, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.gnome.gnomo_feerico', 'ancestry.gnome', FALSE, 'Gnomo Feérico', 'Fey-Touched Gnome', 'Gnomo tocado por las hadas', 'Sua profunda afinidade com o Primeiro Mundo concede conexão mágica com a natureza. Você recebe um truque da tradição primal à sua escolha, conjurado como magia inata primal à vontade.', 'Your close bond with the First World grants you primal power. You gain one primal cantrip of your choice, cast as an at-will primal innate spell.', 'Tu vínculo con el Primer Mundo te otorga magia primordial. Obtienes un truco de la tradición primordial de tu elección, lanzado como conjuro innato a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 56, '{"grants":{"type":"spell","slotId":"1_heritage_innate_spell","tradition":"primal","rank":0,"innate":true,"label":{"pt-BR":"Truque Inato (Gnomo Feérico)","en":"Innate Cantrip (Fey-Touched Gnome)","es":"Truco innato (Gnomo tocado por las hadas)"}},"needs_review":false}'::jsonb),
  ('heritage.ancestry.gnome.gnomo_sensitivo', 'ancestry.gnome', FALSE, 'Gnomo Sensitivo', 'Sensate Gnome', 'Gnomo sensitivo', 'Seu olfato extraordinário percebe odores quase imperceptíveis. Você recebe Faro impreciso em um raio de 9 metros (30 pés) e +2 circunstancial para Procurar com o olfato.', 'Your extraordinary sense of smell detects fine aromas. You gain imprecise scent with a range of 30 feet and a +2 circumstance bonus to Seek using scent.', 'Tu extraordinario sentido del olfato detecta aromas sutiles. Obtienes Olfato impreciso en 9 m y un bonificador circunstancial de +2 para Buscar mediante el olfato.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 56, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.gnome.gnomo_do_umbral', 'ancestry.gnome', FALSE, 'Gnomo do Umbral', 'Umbral Gnome', 'Gnomo umbrío', 'Descendente de gnomos que habitaram cavernas profundas ou o Reino das Sombras, seus olhos se aclimataram à escuridão. Você recebe visão no escuro em vez de visão na penumbra.', 'Adapted to shadowy groves and dark subterranean realms, you possess darkvision instead of low-light vision.', 'Adaptado a reinos subterráneos y sombríos, posees visión en la oscuridad en lugar de visión en la penumbra.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 56, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.gnome.gnomo_poco_de_vigor', 'ancestry.gnome', FALSE, 'Gnomo Poço de Vigor', 'Wellspring Gnome', 'Gnomo manantial', 'Uma fonte infinita de magia de outra tradição flui por sua alma. Escolha uma tradição mágica (arcana, divina ou oculta): você recebe um truque dessa tradição conjurado como magia inata à vontade.', 'An unending wellspring of non-primal magic courses through you. Choose arcane, divine, or occult: you gain one cantrip of that tradition as an at-will innate spell.', 'Un manantial inagotable de magia fluye a través de ti. Elige arcana, divina u oculta: obtienes un truco de esa tradición como conjuro innato a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 56, '{"grants":{"type":"spell","slotId":"1_heritage_innate_spell","rank":0,"innate":true,"label":{"pt-BR":"Truque Inato (Gnomo Poço de Vigor)","en":"Innate Cantrip (Wellspring Gnome)","es":"Truco innato (Gnomo manantial)"}},"needs_review":false}'::jsonb),
  ('heritage.ancestry.goblin.goblin_cabeca_dura', 'ancestry.goblin', FALSE, 'Goblin Cabeça-Dura', 'Unbreakable Goblin', 'Goblin inquebrantable', 'Você possui ossos e crânio extraordinariamente densos e resistentes. Seus Pontos de Vida iniciais de ancestralidade aumentam de 6 para 10, e você sofre metade do dano de quedas.', 'You have an exceptionally dense skull and resilient constitution. Your starting ancestry HP increases from 6 to 10, and you take half damage from falls.', 'Posees un cráneo y huesos increíblemente densos. Tus PG iniciales de ancestro aumentan de 6 a 10 y sufres la mitad del daño por caídas.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 60, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.goblin.goblin_carbonizado_resistencia_a_fogo', 'ancestry.goblin', FALSE, 'Goblin Carbonizado (Resistência a Fogo)', 'Charhide Goblin', 'Goblin de piel carbonizada', 'Sua pele grossa e chamuscada acostumou-se às chamas. Você recebe resistência a fogo igual à metade do seu nível (mínimo 1) e recupera-se de dano de fogo persistente com CD fixa 10 (ou CD 5 com auxílio).', 'Your thick, mottled skin is resistant to flame. You gain fire resistance equal to half your level (minimum 1) and recover from persistent fire damage with flat DC 10 (or DC 5 with assistance).', 'Tu piel gruesa y curtida resiste las llamas. Obtienes resistencia al fuego igual a la mitad de tu nivel (mínimo 1) y te recuperas del daño persistente por fuego con CD pura 10 (o CD 5 con ayuda).', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 60, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.goblin.goblin_irritadico', 'ancestry.goblin', FALSE, 'Goblin Irritadiço', 'Irongut Goblin', 'Goblin de tripa de hierro', 'Seu estômago de ferro consegue digerir praticamente qualquer matéria orgânica. Você recebe +2 circunstancial em salvamentos contra doenças ou venenos ingeridos e nunca passa mal com comida estragada.', 'Your iron constitution allows you to safely consume almost anything. You gain a +2 circumstance bonus to saves against ingested poisons/diseases and cannot get sick from spoiled food.', 'Tu estómago de hierro puede digerir casi cualquier alimento. Obtienes un bonificador circunstancial de +2 contra venenos o enfermedades ingeridos y nunca enfermas por comida en mal estado.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 60, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.goblin.goblin_dente_de_navalha', 'ancestry.goblin', FALSE, 'Goblin Dente-de-Navalha', 'Razortooth Goblin', 'Goblin de dientes afilados', 'Sua boca é repleta de dentes afiados como agulhas que servem como armas perigosas. Você recebe um ataque desarmado de Mandíbulas que causa 1d6 de dano perfurante e possui o traço acuidade (finesse).', 'Your mouth is packed with razor-sharp needles. You gain a Jaws unarmed attack that deals 1d6 piercing damage and has the finesse trait.', 'Tu boca está llena de colmillos afilados. Obtienes un ataque desarmado de Mandíbulas que causa 1d6 de daño perforante y tiene el rasgo sutileza (finesse).', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 60, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.goblin.goblin_macaco', 'ancestry.goblin', FALSE, 'Goblin Macaco', 'Treetop Goblin', 'Goblin arbóreo', 'Seus membros ágeis e cauda ou pés preênseis facilitam a locomoção vertical. Você recebe deslocamento de escalada de 4,5 metros (15 pés) em superfícies de madeira ou rocha natural.', 'Your agile limbs and nimble grip make climbing natural. You gain a climb Speed of 15 feet across wood, trees, and natural stone.', 'Tus extremidades ágiles facilitan la escalada vertical. Obtienes una velocidad de escalada de 4,5 m (15 pies) en madera y roca natural.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 60, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.halfling.halfling_pes_leves', 'ancestry.halfling', FALSE, 'Halfling Pés-Leves', 'Nomadic Halfling', 'Halfling nómada', 'Seus passos silenciosos e rápidos permitem que você se mova com destreza inigualável. Seu deslocamento terrestre aumenta em +1,5 metro (+5 pés), alcançando 9 metros (30 pés).', 'Your swift, light feet carry you across great distances. Your base land Speed increases by 5 feet (to 30 feet).', 'Tus pasos rápidos y ligeros te permiten moverte con agilidad. Tu velocidad terrestre base aumenta en +1,5 m (+5 pies) hasta 9 m (30 pies).', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 64, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.halfling.halfling_destemido', 'ancestry.halfling', FALSE, 'Halfling Destemido', 'Gutsy Halfling', 'Halfling valiente', 'Sua bravura natural resiste até ao mais terrível terror. Sempre que obtiver um sucesso em teste de resistência contra efeitos de medo ou emoção, você obtém um sucesso decisivo.', 'Your brave spirit refuses to cower. Whenever you roll a success on a saving throw against an emotion or fear effect, you get a critical success instead.', 'Tu espíritu valiente se niega a acobardarse. Siempre que obtengas un éxito en una tirada de salvación contra miedo o emoción, obtienes un éxito crítico.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 64, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.halfling.halfling_esguio', 'ancestry.halfling', FALSE, 'Halfling Esguio', 'Twilight Halfling', 'Halfling del crepúsculo', 'Sua visão adaptou-se às sombras da noite e à penumbra. Você recebe visão na penumbra e recebe +1 de bônus circunstancial em testes de Furtividade na penumbra ou escuridão.', 'Your keen eyes pierce the gloom. You gain low-light vision and a +1 circumstance bonus to Stealth checks in dim light or darkness.', 'Tus ojos penetran la penumbra. Obtienes visión en la penumbra y un bonificador circunstancial de +1 a Sigilo en luz tenue u oscuridad.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 64, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.halfling.halfling_nomade_da_colina', 'ancestry.halfling', FALSE, 'Halfling Nômade da Colina', 'Hillock Halfling', 'Halfling de colina', 'O aconchego e o descanso recuperam seu vigor muito mais rapidamente. Sempre que descansar durante a noite ou receber cuidados com Tratar Ferimentos, você recupera PV adicionais iguais ao seu nível + modificador de Constituição.', 'Rest and comfort restore your energy rapidly. Whenever you rest overnight or receive Treat Wounds, you regain additional HP equal to your level + Constitution modifier.', 'El descanso restaura tu vigor con rapidez. Cada vez que descanses toda la noche o recibas Tratar heridas, recuperas PG adicionales iguales a tu nivel + mod. de Constitución.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 64, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.halfling.halfling_abencoado_pela_sorte', 'ancestry.halfling', FALSE, 'Halfling Abençoado pela Sorte', 'Wildwood Halfling', 'Halfling bosqueagreste', 'Você navega por matas e terrenos acidentados com fluidez natural. Você ignora terreno difícil não-mágico causado por plantas, raízes, arbustos e folhagens.', 'You slip through dense foliage effortlessly. You ignore non-magical difficult terrain caused by plants, thickets, undergrowth, and vines.', 'Te deslizas por la vegetación con fluidez. Ignoras el terreno difícil no mágico causado por plantas, maleza y follaje.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 64, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.leshy.leshy_folhoso', 'ancestry.leshy', FALSE, 'Leshy Folhoso', 'Leaf Leshy', 'Leshy de hojas', 'Seu corpo é coberto por folhas largas e flexíveis que amortecem quedas. Você planar lentamente pelo ar enquanto estiver consciente, não sofrendo dano de queda algum.', 'Your body is covered in broad, buoyant foliage. You glide gently through the air while conscious, taking 0 damage from falling.', 'Tu cuerpo está cubierto de hojas amplias y flexibles. Planeas suavemente mientras estés consciente, sin sufrir daño por caída.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 68, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.leshy.leshy_frutifero', 'ancestry.leshy', FALSE, 'Leshy Frutífero', 'Fruit Leshy', 'Leshy frutal', 'Seu corpo produz frutos mágicos e revigorantes a cada amanhecer. Você pode colher um fruto nutritivo por dia que cura Pontos de Vida iguais a 1d8 + seu nível quando consumido.', 'Your body grows nourishing magical fruit each day. You produce a fruit daily that restores HP equal to 1d8 + your level when eaten.', 'Tu cuerpo produce frutos mágicos y reconstituyentes. Creas un fruto diario que restaura 1d8 + tu nivel en PG al consumirse.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 68, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.leshy.leshy_espinhoso', 'ancestry.leshy', FALSE, 'Leshy Espinhoso', 'Spine Leshy', 'Leshy de espinas', 'Seu corpo possui espinhos afiados que podem ser disparados contra ameaças. Você recebe um ataque desarmado à distância de Espinhos com alcance de 3 metros (10 pés) que causa 1d4 de dano perfurante.', 'Sharp quills cover your form. You gain a Spine ranged unarmed attack with a range increment of 10 feet that deals 1d4 piercing damage.', 'Espinas afiladas cubren tu cuerpo. Obtienes un ataque desarmado a distancia de Espinas con alcance de 3 m que causa 1d4 de daño perforante.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 68, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.leshy.leshy_fungico', 'ancestry.leshy', FALSE, 'Leshy Fúngico', 'Fungus Leshy', 'Leshy fúngico', 'Formado a partir de cogumelos, micélios e fungos subterrâneos, você floresce na escuridão. Você recebe visão no escuro em vez de visão na penumbra.', 'Formed from mycelium and subterranean mushrooms, you thrive without sunlight. You gain darkvision instead of low-light vision.', 'Formado a partir de micelio y hongos subterráneos, floreces sin luz solar. Obtienes visión en la oscuridad en lugar de visión en la penumbra.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 68, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.leshy.leshy_da_flor_de_lotus', 'ancestry.leshy', FALSE, 'Leshy da Flor de Lótus', 'Lotus Leshy', 'Leshy de loto', 'Seu corpo de lírio aquático flutua perfeitamente sobre a água. Você consegue caminhar sobre águas calmas sem afundar e recebe +2 de bônus circunstancial em testes de Atletismo para Nadar.', 'Your water lily composition allows you to glide atop calm water surfaces without sinking, and gives +2 circumstance to Athletics checks to Swim.', 'Tu composición de nenúfar te permite caminar sobre el agua en calma sin hundirte y te otorga +2 circunstancial a Nadar.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 68, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.orc.orc_dos_ermos', 'ancestry.orc', FALSE, 'Orc dos Ermos', 'Badlands Orc', 'Orco de las tierras baldías', 'Acostumado ao clima impiedoso das terras áridas, você resiste aos rigores da estepe. Você trata calor e frio ambiental como um grau menos severo e reduz a fadiga de marchas forçadas.', 'Accustomed to baking sun and freezing winds, you treat hot and cold environments as one step less severe and reduce forced march fatigue.', 'Acostumbrado al clima hostil de las estepas, tratas el calor y frío ambiental como un paso menos severos y reduces la fatiga por marcha forzada.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 72, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.orc.orc_couro_de_batalha', 'ancestry.orc', FALSE, 'Orc Couro-de-Batalha', 'Battle-Ready Orc', 'Orco listo para la batalla', 'Treinado desde a infância na arte do combate intimidatório, você se torna treinado em Intimidação e recebe o talento Olhar Intimidador (Intimidating Glare).', 'Hardened by early martial training, you become trained in Intimidation and gain the Intimidating Glare skill feat.', 'Endurecido por el entrenamiento marcial temprano, quedas entrenado en Intimidación y obtienes la dote Mirada intimidante.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 72, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.orc.orc_da_chuva_profunda', 'ancestry.orc', FALSE, 'Orc da Chuva Profunda', 'Deep-Orc', 'Orco de las profundidades', 'Adaptado aos túneis úmidos e cavernas profundas, você recebe Faro impreciso em um raio de 9 metros (30 pés) e +1 de bônus circunstancial em Percepção para Procurar no subsolo.', 'Adapted to damp subterranean tunnels, you gain imprecise scent with a range of 30 feet and a +1 circumstance bonus to Seek underground.', 'Adaptado a túneles subterráneos húmedos, obtienes Olfato impreciso en 9 m y un bonificador circunstancial de +1 para Buscar bajo tierra.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 72, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.orc.orc_cicatrizado', 'ancestry.orc', FALSE, 'Orc Cicatrizado', 'Hold-Scarred Orc', 'Orco con cicatrices de clan', 'Seu corpo carrega cicatrizes de rituais e batalhas incontáveis. Seus Pontos de Vida de ancestralidade aumentam de 10 para 12 e você recebe o talento geral Duro de Matar (Diehard).', 'Your body bears marks of ritual trials. Your starting ancestry HP increases from 10 to 12 and you gain the Diehard general feat.', 'Tu cuerpo luce cicatrices de innumerables batallas. Tus PG de ancestro aumentan de 10 a 12 y obtienes la dote general Duro de matar.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 72, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.orc.orc_presa_de_ferro', 'ancestry.orc', FALSE, 'Orc Presa-de-Ferro', 'Grave Orc', 'Orco sepulcral', 'Nascido em túmulos ancestrais ou cemitérios de guerra, seu sangue repele a morte. Você recebe resistência a dano de Vazio igual à metade do seu nível (mínimo 1) e +1 circunstancial contra efeitos de morte.', 'Born in ancestral crypts or battlegrounds, your blood resists death magic. You gain void resistance equal to half your level (min 1) and +1 to saves vs death effects.', 'Nacido en cementerios ancestrales, obtienes resistencia al daño de Vacío igual a la mitad de tu nivel (mín. 1) y +1 contra efectos de muerte.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core)', 72, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.catfolk.povo_gato_cacador', 'ancestry.catfolk', FALSE, 'Povo-Gato Caçador', 'Hunting Catfolk', 'Catfolk cazador', 'Você possui olfato refinado para rastrear presas. Você recebe Faro impreciso em um raio de 9 metros (30 pés) e +2 de bônus circunstancial em testes de Sobrevivência para Rastrear criaturas farejadas.', 'You have refined olfactory senses. You gain imprecise scent with a range of 30 feet and a +2 circumstance bonus to Track creatures with scent.', 'Posees un olfato refinado para cazar. Obtienes Olfato impreciso en 9 m y un bonificador circunstancial de +2 a Rastrear criaturas con el olfato.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.catfolk.povo_gato_garra_flexivel', 'ancestry.catfolk', FALSE, 'Povo-Gato Garra-Flexível', 'Clawed Catfolk', 'Catfolk con garras', 'Suas garras retráteis são armas letais e afiadas. Você recebe um ataque desarmado de Garras que causa 1d6 de dano cortante com os traços ágil e acuidade (finesse).', 'Your retractable claws are sharp lethal weapons. You gain a Claw unarmed attack that deals 1d6 slashing damage with agile and finesse traits.', 'Tus garras retráctiles son armas letales. Obtienes un ataque desarmado de Garras que causa 1d6 de daño cortante con los rasgos ágil y sutileza.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.catfolk.povo_gato_nove_vidas', 'ancestry.catfolk', FALSE, 'Povo-Gato Nove-Vidas', 'Nine-Lives Catfolk', 'Catfolk de nueve vidas', 'Você possui uma fortuna sobrenatural que desafia a morte. Quando um acerto crítico reduzir seus PV a 0, sua condição morrendo aumenta em apenas 1 em vez de 2, e você recebe o talento Duro de Matar.', 'You possess uncanny luck when facing death. When a critical hit reduces you to 0 HP, your dying condition increases by only 1 instead of 2, and you gain Diehard.', 'Posees una fortuna sobrenatural ante la muerte. Cuando un golpe crítico te reduce a 0 PG, tu condición moribundo aumenta en 1 en lugar de 2, y obtienes Duro de matar.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.catfolk.povo_gato_da_selva', 'ancestry.catfolk', FALSE, 'Povo-Gato da Selva', 'Jungle Catfolk', 'Catfolk de la selva', 'Seu equilíbrio permite que você ignore folhagens densas e raízes. Você ignora terreno difícil causado por vegetação não-mágica e recebe +1 circunstancial em salvamentos de Reflexos em florestas e selvas.', 'Your balance allows you to sprint through thick undergrowth. You ignore difficult terrain from non-magical foliage and gain +1 circumstance to Reflex in jungles.', 'Tu equilibrio te permite correr por la maleza espesa. Ignoras el terreno difícil por vegetación no mágica y obtienes +1 circunstancial a Reflejos en selvas.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.ratfolk.povo_rato_das_profundezas', 'ancestry.ratfolk', FALSE, 'Povo-Rato das Profundezas', 'Deep Ratfolk', 'Ysoki de las profundidades', 'Criado nos túneis e catacumbas mais escuras, sua visão opera sem necessidade de luz. Você recebe visão no escuro em vez de visão na penumbra.', 'Raised in subterranean tunnels and catacombs, you navigate lightless depths with ease. You gain darkvision instead of low-light vision.', 'Criado en túneles subterráneos y catacumbas, navegas sin luz. Obtienes visión en la oscuridad en lugar de visión en la penumbra.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 20, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.ratfolk.povo_rato_da_tempestade', 'ancestry.ratfolk', FALSE, 'Povo-Rato da Tempestade', 'Desert Ratfolk', 'Ysoki del desierto', 'Adaptado às dunas áridas e tempestades de areia, seu organismo retém água com perfeição. Você recebe resistência a fogo igual à metade do seu nível (mínimo 1) e necessita de apenas metade da água normal.', 'Acclimated to scorching desert sands, you retain moisture effectively. You gain fire resistance equal to half your level (min 1) and require half the normal water.', 'Adaptado a las dunas y tormentas de arena, retienes la hidratación. Obtienes resistencia al fuego igual a la mitad de tu nivel (mín. 1) y necesitas la mitad de agua.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 20, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.ratfolk.povo_rato_bochecha_longa', 'ancestry.ratfolk', FALSE, 'Povo-Rato Bochecha Longa', 'Longcheek Ratfolk', 'Ysoki de mejillas largas', 'Suas bolsas nas bochechas são elásticas e espaçosas. Você pode armazenar até 1 Volume de itens em suas bochechas e recebe +2 de bônus circunstancial em testes de Furtividade para ocultá-los.', 'Your cheek pouches are unusually elastic. You can store up to 1 Bulk of objects inside your cheek pouches and gain a +2 circumstance bonus to Stealth to conceal them.', 'Tus bolsas en las mejillas son muy elásticas. Puedes almacenar hasta 1 Volumen de objetos en ellas y obtienes +2 circunstancial a Sigilo para ocultarlos.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 20, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.ratfolk.povo_rato_dos_tuneis', 'ancestry.ratfolk', FALSE, 'Povo-Rato dos Túneis', 'Tunnel Ratfolk', 'Ysoki de los túneles', 'Seu corpo flexível desliza por aberturas minúsculas sem perder velocidade. Você pode Espremer-se com seu deslocamento normal e não fica desprevenido/desprotegido ao fazê-lo.', 'Your flexible bone structure lets you glide through narrow gaps. You Squeeze at full Speed and do not become off-guard while squeezing.', 'Tu cuerpo flexible se desliza por huecos estrechos. Te Escurres a velocidad normal y no quedas desprevenido al hacerlo.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 20, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kobold.kobold_escama_draconica', 'ancestry.kobold', FALSE, 'Kobold Escama-Dracônica', 'Dragonscaled Kobold', 'Kobold de escamas dracónicas', 'Suas escamas refletem o poder elemental do seu exemplar dracônico. Você recebe resistência igual ao seu nível ao tipo de dano elemental do seu dragão (fogo, frio, eletricidade, ácido ou veneno).', 'Your scales shine with your draconic exemplar''s power. You gain resistance equal to your level against your exemplar''s energy type (acid, cold, electricity, fire, or poison).', 'Tus escamas brillan con el poder de tu dragón patrón. Obtienes resistencia igual a tu nivel al tipo de daño de tu ejemplar dracónico.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 26, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kobold.kobold_venenoso', 'ancestry.kobold', FALSE, 'Kobold Venenoso', 'Venomtail Kobold', 'Kobold de cola venenosa', 'Sua cauda é armada com um ferrão afiado e glândulas de toxina. Você recebe um ataque desarmado de Cauda que causa 1d6 de dano perfurante com acuidade (finesse) e traço desarmado.', 'Your tail terminates in a sharp stinger. You gain a Tail unarmed attack that deals 1d6 piercing damage with the finesse trait.', 'Tu cola termina en un aguijón afilado. Obtienes un ataque desarmado de Cola que causa 1d6 de daño perforante con el rasgo sutileza.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 26, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kobold.kobold_cavernoso', 'ancestry.kobold', FALSE, 'Kobold Cavernoso', 'Cavern Kobold', 'Kobold cavernario', 'Seu corpo foi moldado para escavar e rastejar por fendas de pedra. Você pode Espremer-se com velocidade normal e recebe +1 circunstancial em testes de Atletismo para Escalar rochas naturais.', 'You were bred to navigate tight mine shafts. You Squeeze at full Speed and gain a +1 circumstance bonus to Athletics checks to Climb natural rock.', 'Tu cuerpo está moldeado para gatear por túneles estrechos. Te Escurres a velocidad normal y obtienes +1 circunstancial a Escalar roca natural.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 26, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kobold.kobold_tece_feitico', 'ancestry.kobold', FALSE, 'Kobold Tece-Feitiço', 'Spellscale Kobold', 'Kobold tejehechizos', 'Acentuada magia dracônica desperta em seu sangue. Escolha um truque da lista de magias arcanas ou divinas de acordo com seu dragão; você o conjura como magia inata à vontade.', 'Draconic magic resonates in your bloodline. Choose one arcane or divine cantrip matching your dragon exemplar; you cast it as an at-will innate spell.', 'La magia dracónica despierta en tu sangre. Elige un truco arcano o divino afín a tu ejemplar; lo lanzas como conjuro innato a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 26, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.lizardfolk.iruxi_dos_penhascos', 'ancestry.lizardfolk', FALSE, 'Iruxi dos Penhascos', 'Cliff Lizardfolk', 'Iruxi de los acantilados', 'Suas garras e almofadas digitais aderem com firmeza a pedras verticais. Você recebe deslocamento de escalada de 4,5 metros (15 pés) e +2 circunstancial em Atletismo para Escalar.', 'Your toe pads and curved claws grip sheer rock faces. You gain a climb Speed of 15 feet and a +2 circumstance bonus to Climb.', 'Tus garras y dedos se adhieren a riscos verticales. Obtienes una velocidad de escalada de 4,5 m y un bonificador circunstancial de +2 a Escalar.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 32, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.lizardfolk.iruxi_aquatico', 'ancestry.lizardfolk', FALSE, 'Iruxi Aquático', 'Wetlander Lizardfolk', 'Iruxi de humedal', 'Seus membros palmados e pulmões adaptados tornam você um nadador perfeito. Você recebe deslocamento de natação de 7,5 metros (25 pés) e pode prender a respiração por até 2 horas.', 'Your webbed digits and adapted physiology allow you to swim effortlessly. You gain a swim Speed of 25 feet and can hold your breath for up to 2 hours.', 'Tus extremidades palmeadas te convierten en un nadador nato. Obtienes una velocidad de nado de 7,5 m y puedes aguantar la respiración hasta 2 horas.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 32, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.lizardfolk.iruxi_couro_de_placas', 'ancestry.lizardfolk', FALSE, 'Iruxi Couro-de-Placas', 'Frilled Lizardfolk', 'Iruxi con gola', 'Você possui uma gola retrátil intimidadora ao redor do pescoço. Você se torna treinado em Intimidação e pode abrir sua gola para Desmoralizar múltiplos inimigos a até 9 metros.', 'You have a menacing neck frill that splays outward. You become trained in Intimidation and can splay your frill to Demoralize foes within 30 feet.', 'Posees una gola retráctil intimidante. Quedas entrenado en Intimidación y puedes desplegar tu gola para Desmoralizar enemigos a 9 m.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 32, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.lizardfolk.iruxi_cacador_noturno', 'ancestry.lizardfolk', FALSE, 'Iruxi Caçador Noturno', 'Unseen Lizardfolk', 'Iruxi invisible', 'Suas escamas mudam de pigmento camuflando-se com os pântanos e florestas. Você recebe +2 de bônus circunstancial em Furtividade para Esconder-se e pode Esconder-se sem cobertura total.', 'Your scales shift pigment to match damp foliage. You gain a +2 circumstance bonus to Stealth to Hide and can Hide without total cover.', 'Tus escamas cambian de color mimetizándose con el entorno. Obtienes un bonificador circunstancial de +2 a Sigilo para Esconderte.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 32, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kitsune.kitsune_celestial', 'ancestry.kitsune', FALSE, 'Kitsune Celestial', 'Celestial Kitsune', 'Kitsune celestial', 'Sua linhagem é abençoada por divindades celestiais e espíritos bondosos. Você recebe o truque luz como magia inata divina à vontade e recebe +1 circunstancial contra maldições.', 'Blessed by benevolent spirits and kami, you gain the light cantrip as an at-will divine innate spell and a +1 circumstance bonus to saves vs curses.', 'Bendecido por espíritos benévolos, obtienes el truco luz como conjuro innato divino a voluntad y +1 circunstancial contra maldiciones.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 120, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kitsune.kitsune_da_terra', 'ancestry.kitsune', FALSE, 'Kitsune da Terra', 'Earthly Kitsune', 'Kitsune terrenal', 'Sua forma natural de raposa é robusta e ágil. Você recebe um ataque desarmado de Mandíbulas que causa 1d6 de dano perfurante com acuidade (finesse) em sua forma de raposa ou híbrida.', 'Your fox form is agile and predatory. You gain a Jaws unarmed attack that deals 1d6 piercing damage with the finesse trait.', 'Tu forma de zorro es ágil y cazadora. Obtienes un ataque desarmado de Mandíbulas que causa 1d6 de daño perforante con sutileza.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 120, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kitsune.kitsune_espiritual', 'ancestry.kitsune', FALSE, 'Kitsune Espiritual', 'Spirit Kitsune', 'Kitsune espiritual', 'Você transita entre o mundo físico e o espiritual. Você recebe o truque toque gélido / distorcer vazio (void warp) como magia inata oculta à vontade.', 'You walk the threshold between the mortal world and the spirit world. You gain the void warp cantrip as an at-will occult innate spell.', 'Caminas entre el mundo mortal y el espiritual. Obtienes el truco distorsión del vacío como conjuro innato ocultista a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 120, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kitsune.kitsune_fogo_fatuo', 'ancestry.kitsune', FALSE, 'Kitsune Fogo-Fátuo', 'Wisp Kitsune', 'Kitsune fuego fatuo', 'Você manifesta pequenas chamas espirituais que dançam no ar. Você pode conjurar luzes dançantes (dancing lights) como magia inata oculta à vontade.', 'You manifest orbs of glowing foxfire. You can cast the dancing lights (light) cantrip as an at-will occult innate spell.', 'Manifiestas orbes de fuego espiritual. Puedes lanzar luces danzantes como conjuro innato ocultista a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 120, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tengu.tengu_bico_de_navalha', 'ancestry.tengu', FALSE, 'Tengu Bico-de-Navalha', 'Jabbing Tengu', 'Tengu de pico afilado', 'Seu bico longo e afiado é uma arma formidável em combate corpo a corpo. Você recebe um ataque desarmado de Bico que causa 1d6 de dano perfurante com acuidade (finesse) e ágil.', 'Your sharp, long beak is a dangerous weapon. You gain a Beak unarmed attack that deals 1d6 piercing damage with agile and finesse traits.', 'Tu pico largo y afilado es un arma peligrosa. Obtienes un ataque desarmado de Pico que causa 1d6 de daño perforante con ágil y sutileza.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 38, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tengu.tengu_olho_da_tempestade', 'ancestry.tengu', FALSE, 'Tengu Olho-da-Tempestade', 'Stormtossed Tengu', 'Tengu de la tempestad', 'Nascido sob raios e vendavais, a eletricidade não o perturba. Você recebe resistência a eletricidade igual à metade do seu nível (mínimo 1) e ignora penalidades visuais de clima adverso.', 'Born under thunderclaps and howling gales, you gain electricity resistance equal to half your level (min 1) and ignore visual weather penalties.', 'Nacido entre rayos y vendavales, obtienes resistencia a la electricidad igual a la mitad de tu nivel (mín. 1) e ignoras penalizadores visuales por clima.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 38, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tengu.tengu_asa_ceu', 'ancestry.tengu', FALSE, 'Tengu Asa-Céu', 'Skyborn Tengu', 'Tengu nacido del cielo', 'Suas asas e penas abrem-se instintivamente para desacelerar quedas. Você não sofre dano de quedas de até 9 metros e recebe +2 circunstancial em Atletismo para Saltos Altos.', 'Your plumage and wings instinctively brake your falls. You take no falling damage from falls up to 30 feet and gain +2 circumstance to High Jump.', 'Tus alas y plumaje amortiguan tus caídas. No sufres daño por caídas de hasta 9 m y obtienes +2 circunstancial a Salto de altura.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 38, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tengu.tengu_da_montanha', 'ancestry.tengu', FALSE, 'Tengu da Montanha', 'Mountain Tengu', 'Tengu de la montaña', 'Habitante dos picos nevados e mosteiros rochosos, você recebe resistência a frio igual à metade do seu nível (mínimo 1) e +2 circunstancial em testes de Atletismo para Escalar rochas.', 'Hailing from snowy peaks and mountaintop shrines, you gain cold resistance equal to half your level (min 1) and +2 circumstance to Climb rock.', 'Habitante de riscos nevados, obtienes resistencia al frío igual a la mitad de tu nivel (mín. 1) y +2 circunstancial a Escalar roca.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 38, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tripkee.tripkee_peletoxica', 'ancestry.tripkee', FALSE, 'Tripkee Peletóxica', 'Poisonhide Tripkee', 'Tripkee piel tóxica', 'Sua pele úmida secreta uma toxina defensiva. Qualquer criatura que o agarrar ou atacar desarmada com a boca sofre dano de veneno igual à metade do seu nível (mínimo 1).', 'Your skin secretes a potent defensive toxin. Any creature that grapples you or bites you takes poison damage equal to half your level (min 1).', 'Tu piel segrega una toxina defensiva. Cualquier criatura que te agarre o muerda sufre daño de veneno igual a la mitad de tu nivel (mín. 1).', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 40, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tripkee.tripkee_ribeirinho', 'ancestry.tripkee', FALSE, 'Tripkee Ribeirinho', 'Stream Tripkee', 'Tripkee fluvial', 'Você nada velozmente através de rios e lagos. Você recebe deslocamento de natação de 7,5 metros (25 pés) e pode prender a respiração por até 30 minutos debaixo d''água.', 'You swim effortlessly through freshwater streams. You gain a swim Speed of 25 feet and can hold your breath for up to 30 minutes.', 'Nadas con facilidad por ríos y lagos. Obtienes una velocidad de nado de 7,5 m y puedes aguantar la respiración hasta 30 minutos.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 40, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tripkee.tripkee_linguaveloz', 'ancestry.tripkee', FALSE, 'Tripkee Línguaveloz', 'Snapping Tripkee', 'Tripkee lenguaveloz', 'Sua língua elástica dispara como um chicote. Você recebe um ataque desarmado de Língua com alcance de 3 metros (10 pés) que causa 1d4 de dano de concussão com traço desarmado e acuidade.', 'Your elastic tongue lashes out at prey. You gain a Tongue unarmed attack with a 10-foot reach that deals 1d4 bludgeoning damage with finesse.', 'Tu lengua elástica se dispara con rapidez. Obtienes un ataque desarmado de Lengua con alcance de 3 m que causa 1d4 de daño contundente con sutileza.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 40, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tripkee.tripkee_dedoaderente', 'ancestry.tripkee', FALSE, 'Tripkee Dedoaderente', 'Stickytoe Tripkee', 'Tripkee dedos adherentes', 'Almofadas adesivas em suas mãos e pés facilitam a escalada vertical. Você recebe deslocamento de escalada de 4,5 metros (15 pés) em árvores e superfícies lisas.', 'Suction pads on your hands and feet give you a climb Speed of 15 feet across wood, stone, and sheer vertical walls.', 'Almohadillas adhesivas en tus extremidades te otorgan una velocidad de escalada de 4,5 m en paredes y árboles.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 40, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tripkee.tripkee_peledura', 'ancestry.tripkee', FALSE, 'Tripkee Peledura', 'Thickskin Tripkee', 'Tripkee piel gruesa', 'Sua pele grossa e verrugosa atua como armadura natural. Você recebe +1 de bônus de armadura na CA contra ataques cortantes e perfurantes.', 'Your thick, warty hide protects you from slashing and piercing blows, granting natural armor resistance.', 'Tu piel gruesa y verrugosa te protege contra ataques cortantes y perforantes, otorgándote armadura natural.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 40, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.tripkee.tripkee_flutuante', 'ancestry.tripkee', FALSE, 'Tripkee Flutuante', 'Windcatcher Tripkee', 'Tripkee planeador', 'Membranas entre seus dedos e flancos permitem planar no ar. Enquanto estiver consciente, você desacelera sua queda, sofrendo 0 de dano por quedas.', 'Flaps of skin along your limbs allow you to glide through the canopy, taking 0 damage from falling while conscious.', 'Membranas entre tus extremidades te permiten planear en el aire, sufriendo 0 daño por caídas mientras estés consciente.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 40, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.azarketi.azarketi_dos_mares_profundos', 'ancestry.azarketi', FALSE, 'Azarketi dos Mares Profundos', 'Deepwater Azarketi', 'Azarketi de aguas profundas', 'Acostumado à pressão esmagadora e ao frio abissal dos oceanos, você recebe visão no escuro, resistência a frio igual à metade do seu nível e suporta qualquer profundidade aquática.', 'Adapted to freezing abyss depths, you gain darkvision, cold resistance equal to half your level, and ignore oceanic pressure.', 'Adaptado al frío y presión de las profundidades oceánicas, obtienes visión en la oscuridad, resistencia al frío igual a la mitad de tu nivel e ignoras la presión acuática.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 16, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.azarketi.azarketi_fluvial', 'ancestry.azarketi', FALSE, 'Azarketi Fluvial', 'Riverborn Azarketi', 'Azarketi fluvial', 'Habitante de rios caudalosos e corredeiras, sua natação é veloz. Seu deslocamento de natação aumenta para 10,5 metros (35 pés) e você recebe +2 circunstancial em Atletismo para Nadar contra correntes.', 'Raised in rushing rivers, your swim Speed increases to 35 feet and you gain +2 circumstance to Swim against strong currents.', 'Criado en ríos caudalosos, tu velocidad de nado aumenta a 10,5 m (35 pies) y obtienes +2 circunstancial a Nadar contra corriente.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 16, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.azarketi.azarketi_escamado', 'ancestry.azarketi', FALSE, 'Azarketi Escamado', 'Spined Azarketi', 'Azarketi espinoso', 'Barbatanas espinhosas e venenosas recobrem seus braços. Criaturas que o agarrarem sofrem 1d4 de dano perfurante e você recebe um ataque desarmado de Barbatana Espinhosa.', 'Spiny dorsal fins protect you. Creatures that grapple you take 1d4 piercing damage and you gain a Spined Fin unarmed attack.', 'Aletas espinosas protegen tu cuerpo. Las criaturas que te agarren sufren 1d4 de daño perforante y obtienes un ataque desarmado de Aleta espinosa.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 16, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.azarketi.azarketi_nevoa', 'ancestry.azarketi', FALSE, 'Azarketi Névoa', 'Mist Azarketi', 'Azarketi de la niebla', 'Você manipula a umidade atmosférica para ocultar sua presença. Você recebe a magia obscurecimento (fog cloud) ou jato d''água (hydraulic push) como magia inata primal uma vez ao dia.', 'You manipulate coastal mist to veil yourself. You can cast fog cloud or hydraulic push as a 1st-rank primal innate spell once per day.', 'Manipulas la niebla costera para ocultarte. Puedes lanzar nube de niebla como conjuro innato primordial una vez al día.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 16, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.automaton.automato_blindado', 'ancestry.automaton', FALSE, 'Autômato Blindado', 'Armored Automaton', 'Autómata blindado', 'Seu chassi de metal é fortificado com placas de liga antiga. Você recebe +1 de bônus circunstancial na CA contra acertos críticos de ataques cortantes e perfurantes.', 'Your chassis is reinforced with ancient alchemical metal. You gain a +1 circumstance bonus to AC against critical hits from physical attacks.', 'Tu chasis está reforzado con aleaciones antiguas. Obtienes un bonificador circunstancial de +1 a la CA contra golpes críticos de ataques físicos.', NULL, '{}'::text[], 'common', 'legacy', 'Pólvora e Engrenagens (Guns & Gears)', 38, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.automaton.automato_de_caca_veloz', 'ancestry.automaton', FALSE, 'Autômato de Caça Veloz', 'Hunter Automaton', 'Autómata cazador', 'Engrenagens de precisão nos pistões inferiores aumentam sua agilidade motora. Seu deslocamento terrestre base aumenta de 7,5m para 9 metros (30 pés).', 'Precision pistons and balanced gyros accelerate your stride. Your base land Speed increases from 25 feet to 30 feet.', 'Pistones de precisión aceleran tu paso. Tu velocidad terrestre base aumenta de 7,5 m a 9 m (30 pies).', NULL, '{}'::text[], 'common', 'legacy', 'Pólvora e Engrenagens (Guns & Gears)', 38, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.automaton.automato_do_nucleo_brilhante', 'ancestry.automaton', FALSE, 'Autômato do Núcleo Brilhante', 'Bright-Core Automaton', 'Autómata de núcleo brillante', 'Seu núcleo de alma emite feixes concentrados de energia viva. Você recebe um ataque desarmado à distância de Raio de Energia com alcance de 9 metros (30 pés) que causa 1d4 de dano de fogo ou energia.', 'Your soul core discharges focused beams of radiant light. You gain an Energy Beam ranged unarmed attack (30 ft range) dealing 1d4 fire damage.', 'Tu núcleo de alma dispara rayos de energía radiante. Obtienes un ataque desarmado a distancia de Rayo de energía (alcance 9 m) que causa 1d4 de daño por fuego.', NULL, '{}'::text[], 'common', 'legacy', 'Pólvora e Engrenagens (Guns & Gears)', 38, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.automaton.automato_guerreiro', 'ancestry.automaton', FALSE, 'Autômato Guerreiro', 'Warrior Automaton', 'Autómata guerrero', 'Forjado para as linhas de frente da guerra de Jistka, seus punhos são maças devastadoras. O dado de dano do seu punho aumenta para 1d6 e você pode infligir dano letal sem penalidades.', 'Forged for vanguard battle lines, your fists strike with immense force. Your fist damage increases to 1d6 and deals lethal damage with no penalty.', 'Forjado para la primera línea de combate, tus puños golpean con fuerza devastadora. El daño de tus puños aumenta a 1d6 y causa daño letal sin penalizador.', NULL, '{}'::text[], 'common', 'legacy', 'Pólvora e Engrenagens (Guns & Gears)', 38, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.android.androide_artesao', 'ancestry.android', FALSE, 'Andróide Artesão', 'Artisan Android', 'Androide artesano', 'Módulos de manufatura e precisão nanotecnológica aprimoram suas mãos. Você se torna treinado em Manufatura (Crafting) e recebe o talento de perícia Manufatura Especializada.', 'Precision manufacturing nanites enhance your hands. You become trained in Crafting and gain the Specialty Crafting skill feat.', 'Nanitos de precisión mejoran tus manos. Quedas entrenado en Artesanía y obtienes la dote Artesanía especializada.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 22, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.android.androide_cacador', 'ancestry.android', FALSE, 'Andróide Caçador', 'Hunter Android', 'Androide cazador', 'Filtros ópticos avançados e sensores térmicos foram instalados em seus olhos. Você recebe visão no escuro e +1 circunstancial em Percepção para Rastrear presas.', 'Advanced optical sensors pierce total darkness. You gain darkvision and a +1 circumstance bonus to Perception to Track targets.', 'Sensores ópticos avanzados penetran la oscuridad absoluta. Obtienes visión en la oscuridad y +1 circunstancial a Percepción para Rastrear.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 22, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.android.androide_sombra', 'ancestry.android', FALSE, 'Andróide Sombra', 'Shadow Android', 'Androide sombra', 'Circuitos de absorção acústica e térmica silenciam seus passos. Você recebe +2 de bônus circunstancial em testes de Furtividade na penumbra ou escuridão.', 'Acoustic-dampening mesh lines your chassis. You gain a +2 circumstance bonus to Stealth checks in dim light or darkness.', 'Circuitos de absorción acústica silencian tus pasos. Obtienes un bonificador circunstancial de +2 a Sigilo en penumbra u oscuridad.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 22, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.android.androide_guerreiro', 'ancestry.android', FALSE, 'Andróide Guerreiro', 'Warrior Android', 'Androide guerrero', 'Módulos de combate bélico alimentam seus reflexos em batalha. Uma vez por dia, você pode ativar sua Onda de Nanites para receber +2 de bônus de estado em uma jogada de ataque ou salvamento.', 'Martial protocols optimize your reflexes. Once per day, you can trigger your Nanite Surge to gain a +2 status bonus to an attack roll or saving throw.', 'Protocolos bélicos optimizan tus reflejos. Una vez al día puedes activar tu Oleada de nanitos para obtener +2 por estado a una tirada de ataque o salvación.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Ancestralidades (Ancestry Guide)', 22, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kholo.kholo_mandibula_de_ferro', 'ancestry.kholo', FALSE, 'Kholo Mandíbula de Ferro', 'Ironjaw Kholo', 'Kholo mandíbula de hierro', 'Suas mandíbulas poderosas trituram ossos e armaduras com facilidade. Seu ataque desarmado de Mandíbulas causa 1d8 de dano perfurante e ganha o traço agarrar (grapple).', 'Your massive jaws crush bone and armor plate. Your Jaws unarmed attack deals 1d8 piercing damage and gains the grapple trait.', 'Tus enormes mandíbulas trituran hueso y metal. Tu ataque desarmado de Mandíbulas causa 1d8 de daño perforante y gana el rasgo agarrar.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 16, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kholo.kholo_dos_desfiladeiros', 'ancestry.kholo', FALSE, 'Kholo dos Desfiladeiros', 'Canyon Kholo', 'Kholo de los cañones', 'Acostumado a caçar em cânions rochosos e encostas íngremes, você recebe deslocamento de escalada de 4,5 metros (15 pés) e +2 circunstancial em Atletismo para Escalar.', 'Raised hunting along canyon ridges, you gain a climb Speed of 15 feet and a +2 circumstance bonus to Climb rocky cliffs.', 'Criado cazando en cañones y riscos escarpados, obtienes una velocidad de escalada de 4,5 m y un bonificador circunstancial de +2 a Escalar.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 16, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.kholo.kholo_fantasma', 'ancestry.kholo', FALSE, 'Kholo Fantasma', 'Ghost Kholo', 'Kholo fantasma', 'Seu pelo cinzento e passos silenciosos tornam você um espectro noturno. Você recebe visão no escuro e +1 de bônus circunstancial em Furtividade ao espreitar à noite.', 'Pale coat and silent pads make you a nocturnal terror. You gain darkvision and a +1 circumstance bonus to Stealth at night.', 'Tu pelaje pálido y pisadas silenciosas te convierten en un terror nocturno. Obtienes visión en la oscuridad y +1 circunstancial a Sigilo de noche.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 16, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.fetchling.kayal_das_sombras_profundas', 'ancestry.fetchling', FALSE, 'Kayal das Sombras Profundas', 'Deep Shadow Kayal', 'Kayal de las sombras profundas', 'Tocado pelas trevas mais densas do Plano das Sombras, você recebe resistência a frio e a dano de Vazio igual à metade do seu nível (mínimo 1).', 'Imbued with the deepest cold of the Shadow Plane, you gain resistance to cold and void damage equal to half your level (min 1).', 'Imbuido de la oscuridad más densa del Plano de las Sombras, obtienes resistencia al frío y al daño de Vacío igual a la mitad de tu nivel (mín. 1).', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.fetchling.kayal_furtivo', 'ancestry.fetchling', FALSE, 'Kayal Furtivo', 'Subversive Kayal', 'Kayal subversivo', 'Você domina a arte do engano e da dissimulação urbana. Você se torna treinado em Enganação (Deception) e recebe o talento de perícia Diversão Prolongada (Lengthy Diversion).', 'You are a master of urban intrigue. You become trained in Deception and gain the Lengthy Diversion skill feat.', 'Dominas el engaño y la intriga urbana. Quedas entrenado en Engaño y obtienes la dote Distracción prolongada.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.fetchling.kayal_sem_rosto', 'ancestry.fetchling', FALSE, 'Kayal Sem Rosto', 'Faceless Kayal', 'Kayal sin rostro', 'As sombras distorcem suas feições e silhueta. Você pode conjurar disfarce ilusório (illusory disguise) como magia inata oculta de 1º círculo uma vez ao dia.', 'Shadows obscure and remold your features. You can cast illusory disguise as a 1st-rank occult innate spell once per day.', 'Las sombras distorsionan tus rasgos. Puedes lanzar disfraz ilusorio como conjuro innato ocultista de 1.er rango una vez al día.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.hobgoblin.hobgoblin_couro_de_ferro', 'ancestry.hobgoblin', FALSE, 'Hobgoblin Couro de Ferro', 'Ironhide Hobgoblin', 'Hobgoblin piel de hierro', 'Sua pele é calejada e dura como couro fervido. Seus Pontos de Vida de ancestralidade aumentam de 8 para 10 e você recebe +1 circunstancial na CA contra acertos críticos.', 'Your skin is tough as hardened leather. Your starting ancestry HP increases from 8 to 10 and you gain +1 circumstance to AC against critical hits.', 'Tu piel es dura como el cuero curtido. Tus PG de ancestro aumentan de 8 a 10 y obtienes +1 circunstancial a la CA contra golpes críticos.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.hobgoblin.hobgoblin_fumegante', 'ancestry.hobgoblin', FALSE, 'Hobgoblin Fumegante', 'Smokeworker Hobgoblin', 'Hobgoblin de la humareda', 'Criado entre forjas militares e fumaça de pólvora, você recebe resistência a fogo igual à metade do seu nível (mínimo 1) e ignora a camuflagem causada por fumaça.', 'Acclimated to smoke and soot, you gain fire resistance equal to half your level (min 1) and ignore concealment caused by smoke.', 'Criado entre forjas militares y humo, obtienes resistencia al fuego igual a la mitad de tu nivel (mín. 1) e ignoras la ocultación por humo.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.hobgoblin.hobgoblin_vanguarda', 'ancestry.hobgoblin', FALSE, 'Hobgoblin Vanguarda', 'Vanguard Hobgoblin', 'Hobgoblin de vanguardia', 'Treinado para manter a linha contra formações de choque inimigas, você recebe +2 de bônus circunstancial na CD de Reflexos e Fortitude contra Empurrar ou Derrubar.', 'Trained to hold formation against heavy charges, you gain a +2 circumstance bonus to Fortitude and Reflex DC against Shove and Trip.', 'Entrenado para mantener la formación frente a cargas enemigas, obtienes +2 circunstancial a la CD de Fortaleza y Reflejos contra Empujar y Derribar.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.skeleton.esqueleto_bucha', 'ancestry.skeleton', FALSE, 'Esqueleto-Bucha', 'Fodder Skeleton', 'Esqueleto de choque', 'Articulações leves e ossos soltos aumentam sua mobilidade. Seu deslocamento terrestre aumenta em +1,5 metro (+5 pés), totalizando 9 metros (30 pés).', 'Loose, lightweight joints give you exceptional agility. Your base land Speed increases by 5 feet (to 30 feet).', 'Articulaciones ligeras aumentan tu velocidad. Tu velocidad terrestre base aumenta en +1,5 m (+5 pies) hasta 9 m (30 pies).', NULL, '{}'::text[], 'common', 'remaster', 'Livro dos Mortos (Book of the Dead)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.skeleton.esqueleto_compacto', 'ancestry.skeleton', FALSE, 'Esqueleto Compacto', 'Compact Skeleton', 'Esqueleto compacto', 'Composto por ossos menores ou de uma criatura pequena, seu tamanho é Pequeno e você pode Espremer-se através de aberturas minúsculas com facilidade extrema.', 'Assembled from smaller remains, your size is Small and you can Squeeze through tight openings with incredible ease.', 'Ensamblado a partir de restos pequeños, tu tamaño es Pequeño y puedes Escurrirte por aberturas diminutas con gran facilidad.', NULL, '{}'::text[], 'common', 'remaster', 'Livro dos Mortos (Book of the Dead)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.skeleton.esqueleto_monstruoso', 'ancestry.skeleton', FALSE, 'Esqueleto Monstruoso', 'Monstrous Skeleton', 'Esqueleto monstruoso', 'Suas mãos terminam em garras afiadas de ossos monstruosos. Você recebe um ataque desarmado de Garras que causa 1d6 de dano cortante com acuidade e ágil.', 'Your hands end in jagged bone talons. You gain a Claw unarmed attack that deals 1d6 slashing damage with agile and finesse.', 'Tus manos terminan en garras de hueso afiladas. Obtienes un ataque desarmado de Garras que causa 1d6 de daño cortante con ágil y sutileza.', NULL, '{}'::text[], 'common', 'remaster', 'Livro dos Mortos (Book of the Dead)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.skeleton.esqueleto_robusto', 'ancestry.skeleton', FALSE, 'Esqueleto Robusto', 'Sturdy Skeleton', 'Esqueleto robusto', 'Ossos grossos e mineralizados resistem a impactos pesados. Seus Pontos de Vida de ancestralidade aumentam de 6 para 10 e você recebe +1 circunstancial em testes de Fortitude.', 'Dense, mineralized bones grant you extra durability. Your starting ancestry HP increases from 6 to 10 and you gain +1 circumstance to Fortitude saves.', 'Huesos densos y mineralizados te otorgan resistencia. Tus PG de ancestro aumentan de 6 a 10 y obtienes +1 circunstancial a Fortaleza.', NULL, '{}'::text[], 'common', 'remaster', 'Livro dos Mortos (Book of the Dead)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.centaur.centauro_orador_nascente', 'ancestry.centaur', FALSE, 'Centauro Orador Nascente', 'Dawn Speaker Centaur', 'Centauro orador del alba', 'Você aprendeu a sabedoria das estrelas e do amanhecer. Você se torna treinado em Natureza ou Religião e recebe o truque orientação (guidance) como magia inata primal à vontade.', 'Communing with the rising sun and starry skies, you become trained in Nature or Religion and gain guidance as an at-will primal innate spell.', 'Conectado con el sol naciente, quedas entrenado en Naturaleza o Religión y obtienes orientación como conjuro innato a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.centaur.centauro_vento_veloz', 'ancestry.centaur', FALSE, 'Centauro Vento-Veloz', 'Windstrider Centaur', 'Centauro galope del viento', 'Nascido para cavalgar em planícies sem fim, seu corpo quadrúpede atinge velocidades incríveis. Seu deslocamento terrestre aumenta para 10,5 metros (35 pés).', 'Bred for endless steppes, your stride matches the wind. Your base land Speed increases to 35 feet.', 'Nacido para correr en llanuras infinitas, tu velocidad terrestre base aumenta a 10,5 m (35 pies).', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.centaur.centauro_casco_de_ferro', 'ancestry.centaur', FALSE, 'Centauro Casco de Ferro', 'Ironhoof Centaur', 'Centauro casco de hierro', 'Seus cascos são pesados e duros como bigornas. Você recebe um ataque desarmado de Cascos que causa 1d8 de dano de concussão com os traços desarmado e empurrar (shove).', 'Your hooves strike with sledgehammer impact. You gain a Hoof unarmed attack that deals 1d8 bludgeoning damage with shove and unarmed traits.', 'Tus cascos golpean con fuerza de yunque. Obtienes un ataque desarmado de Cascos que causa 1d8 de daño contundente con empujar y desarmado.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.centaur.centauro_malhado', 'ancestry.centaur', FALSE, 'Centauro Malhado', 'Dappled Centaur', 'Centauro moteado', 'Sua pelagem malhada camufla perfeitamente sua silhueta sob a copa das árvores. Você recebe +2 de bônus circunstancial em Furtividade para Esconder-se em florestas e planícies.', 'Your dappled coat blends seamlessly into shadowed glades. You gain a +2 circumstance bonus to Stealth to Hide in forests and grasslands.', 'Tu pelaje moteado se funde con las arboledas. Obtienes un bonificador circunstancial de +2 a Sigilo para Esconderte en bosques.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.centaur.centauro_passo_de_ponei', 'ancestry.centaur', FALSE, 'Centauro Passo de Pônei', 'Ponystep Centaur', 'Centauro poni', 'Descendente de raças equinas menores e compactas, seu tamanho é Médio em vez de Grande, permitindo que você navegue masmorras e portas comuns sem penalidade de aperto.', 'Compact build allows you to navigate dungeons easily. Your size is Medium instead of Large, avoiding squeezing penalties in tight corridors.', 'Tu constitución compacta te permite moverte en mazmorras. Tu tamaño es Mediano en lugar de Grande, evitando penalizadores en pasillos estrechos.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 12, '{"grants":null,"needs_review":false}'::jsonb)
insert into public.catalog_heritages (id, ancestry_id, is_versatile, name_pt, name_en, name_es, description_pt, description_en, description_es, prerequisite, traits, rarity, ruleset, source_book, source_page, data)
values
  ('heritage.ancestry.centaur.centauro_coracao_robusto', 'ancestry.centaur', FALSE, 'Centauro Coração Robusto', 'Stoutheart Centaur', 'Centauro corazón recio', 'Sua coragem inabalável e constituição férrea aumentam seus Pontos de Vida de ancestralidade de 10 para 12 e concedem +1 circunstancial contra medo.', 'Your iron constitution raises your starting ancestry HP from 10 to 12 and grants +1 circumstance to saves vs fear.', 'Tu constitución robusta eleva tus PG de ancestro de 10 a 12 y te otorga +1 circunstancial contra el miedo.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.minotaur.minotauro_touro_fantasma', 'ancestry.minotaur', FALSE, 'Minotauro Touro Fantasma', 'Ghost Bull Minotaur', 'Minotauro toro fantasma', 'Ligado aos labirintos espirituais e ao além, você recebe visão no escuro e pode conjurar orientação (guidance) como magia inata primal à vontade.', 'Tuned to spectral pathways, you gain darkvision and can cast guidance as an at-will primal innate spell.', 'Sintonizado con senderos espectrales, obtienes visión en la oscuridad y lanzas orientación como conjuro innato a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.minotaur.minotauro_da_caverna_glacial', 'ancestry.minotaur', FALSE, 'Minotauro da Caverna Glacial', 'Glacial Cave Minotaur', 'Minotauro glacial', 'Adaptado às geleiras subterrâneas e picos nevados, você recebe resistência a frio igual à metade do seu nível (mínimo 1) e ignora gelo escorregadio.', 'Acclimated to icy caverns, you gain cold resistance equal to half your level (min 1) and ignore difficult terrain from ice.', 'Adaptado a cavernas heladas, obtienes resistencia al frío igual a la mitad de tu nivel (mín. 1) e ignoras el hielo resbaladizo.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.minotaur.minotauro_chifre_pequeno', 'ancestry.minotaur', FALSE, 'Minotauro Chifre Pequeno', 'Littlehorn Minotaur', 'Minotauro cuernocorto', 'Seus chifres compactos e ágeis realizam investidas precisas. Seu ataque desarmado de Chifres ganha o traço acuidade (finesse) e ágil.', 'Your compact horns allow rapid goring attacks. Your Horns unarmed attack gains agile and finesse traits.', 'Tus cuernos compactos permiten embestidas precisas. Tu ataque desarmado de Cuernos gana los rasgos ágil y sutileza.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.minotaur.minotauro_errante', 'ancestry.minotaur', FALSE, 'Minotauro Errante', 'Far-Wanderer Minotaur', 'Minotauro trotamundos', 'Você possui uma bússola interna infalível. Você nunca se perde em labirintos ou no ermo, se torna treinado em Sobrevivência e recebe o talento Rastrear.', 'Your internal sense of direction is flawless. You never become lost, become trained in Survival, and gain the Survey Wildlife or Track feat.', 'Posees una orientación infalible. Nunca te pierdes en laberintos o en la naturaleza, quedas entrenado en Supervivencia y obtienes Rastrear.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.minotaur.minotauro_alma_de_laje', 'ancestry.minotaur', FALSE, 'Minotauro Alma de Laje', 'Slab-Soul Minotaur', 'Minotauro alma de losa', 'Sua pele grossa e ossos densos resistem a impactos. Você recebe +2 circunstancial contra Empurrar e Derrubar, e seus PV de ancestralidade aumentam para 12.', 'Your dense frame anchors you to stone. You gain +2 circumstance to Fortitude against Shove and Trip, and starting ancestry HP increases to 12.', 'Tu cuerpo denso te ancla a la piedra. Obtienes +2 circunstancial contra Empujar y Derribar, y tus PG de ancestro aumentan a 12.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.minotaur.minotauro_espreitador', 'ancestry.minotaur', FALSE, 'Minotauro Espreitador', 'Stalker Minotaur', 'Minotauro acechador', 'Apesar do seu grande porte, você caminha sem fazer ruído. Você se torna treinado em Furtividade e recebe +1 circunstancial para Esconder-se em pedras e cavernas.', 'Despite your size, your hooves step silently. You become trained in Stealth and gain +1 circumstance to Hide in stone environments.', 'A pesar de tu tamaño, caminas en silencio. Quedas entrenado en Sigilo y obtienes +1 circunstancial para Esconderte en piedra y cavernas.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.awakened_animal.animal_escalador', 'ancestry.awakened_animal', FALSE, 'Animal Escalador', 'Climbing Animal', 'Animal trepador', 'Membros e garras fortes permitem navegar pelas copas das árvores. Você recebe deslocamento de escalada de 6 metros (20 pés).', 'Prehensile claws and limbs make climbing natural. You gain a climb Speed of 20 feet.', 'Garras y patas fuertes facilitan la escalada. Obtienes una velocidad de escalada de 6 m (20 pies).', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 24, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.awakened_animal.animal_voador', 'ancestry.awakened_animal', FALSE, 'Animal Voador', 'Flying Animal', 'Animal volador', 'Asas ou membranas funcionais permitem planar e voar curtas distâncias. Enquanto estiver consciente, você não sofre dano algum de quedas.', 'Functional wings or gliding flaps slow your falls, taking 0 damage from falling while conscious.', 'Alas o membranas te permiten planear en el aire, sufriendo 0 daño por caídas mientras estés consciente.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 24, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.awakened_animal.animal_corredor', 'ancestry.awakened_animal', FALSE, 'Animal Corredor', 'Running Animal', 'Animal corredor', 'Pernas compridas e ágeis aceleram seu trote. Seu deslocamento terrestre aumenta em +3 metros (+10 pés), alcançando 10,5 metros (35 pés).', 'Long, powerful legs propel you swiftly. Your base land Speed increases by 10 feet (to 35 feet).', 'Patas largas y potentes aceleran tu marcha. Tu velocidad terrestre base aumenta en +3 m (+10 pies) hasta 10,5 m (35 pies).', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 24, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.awakened_animal.animal_nadador', 'ancestry.awakened_animal', FALSE, 'Animal Nadador', 'Swimming Animal', 'Animal nadador', 'Corpo hidrodinâmico e barbatanas garantem maestria aquática. Você recebe deslocamento de natação de 7,5 metros (25 pés) e pode prender a respiração por até 1 hora.', 'Streamlined build gives you a swim Speed of 25 feet and the ability to hold your breath for up to 1 hour.', 'Cuerpo hidrodinámico que te otorga velocidad de nado de 7,5 m y la capacidad de aguantar la respiración hasta 1 hora.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 24, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.merfolk.povo_sereia_abissal', 'ancestry.merfolk', FALSE, 'Povo-Sereia Abissal', 'Abyssal Merfolk', 'Merfolk abisal', 'Acostumado à escuridão e pressão das fossas oceânicas, você recebe visão no escuro, resistência a frio igual à metade do seu nível (mínimo 1) e imunidade a dano por pressão oceânica.', 'Adapted to freezing lightless oceanic trenches, you gain darkvision, cold resistance equal to half your level (min 1), and pressure immunity.', 'Adaptado a fosas oceánicas heladas y oscuras, obtienes visión en la oscuridad, resistencia al frío igual a la mitad de tu nivel e inmunidad a la presión.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 30, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.merfolk.povo_sereia_carcharodonte', 'ancestry.merfolk', FALSE, 'Povo-Sereia Carcharodonte', 'Carcharodon Merfolk', 'Merfolk carcharodonte', 'Mandíbulas de tubarão repletas de fileiras de dentes serrilhados. Você recebe um ataque desarmado de Mandíbulas que causa 1d8 de dano perfurante com o traço agarrar (grapple).', 'Rows of serrated shark teeth fill your maw. You gain a Jaws unarmed attack that deals 1d8 piercing damage with the grapple trait.', 'Hileras de dientes de tiburón llenan tus mandíbulas. Obtienes un ataque desarmado de Mandíbulas que causa 1d8 de daño perforante con el rasgo agarrar.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 30, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.merfolk.povo_sereia_pelagico', 'ancestry.merfolk', FALSE, 'Povo-Sereia Pelágico', 'Pelagic Merfolk', 'Merfolk pelágico', 'Nascido para nadar em mar aberto, seu deslocamento de natação aumenta para 10,5 metros (35 pés) e você detecta correntes marítimas a até 18 metros.', 'Bred for the open ocean, your swim Speed increases to 35 feet and you can sense oceanic currents within 60 feet.', 'Nacido para nadar en mar abierto, tu velocidad de nado aumenta a 10,5 m (35 pies) y percibes corrientes marítimas en 18 m.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 30, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.merfolk.povo_sereia_de_recife', 'ancestry.merfolk', FALSE, 'Povo-Sereia de Recife', 'Reef Merfolk', 'Merfolk de arrecife', 'Escamas coloridas camuflam você entre corais e anêmonas. Você recebe +2 circunstancial em testes de Furtividade debaixo d''água.', 'Vibrant coloration lets you blend into coral reefs. You gain a +2 circumstance bonus to Stealth checks underwater.', 'Escamas coloridas te camuflan entre corales. Obtienes un bonificador circunstancial de +2 a Sigilo bajo el agua.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 30, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.merfolk.povo_sereia_agulhao', 'ancestry.merfolk', FALSE, 'Povo-Sereia Agulhão', 'Gar Merfolk', 'Merfolk aguja', 'Seu focinho alongado em agulha perfura presas em alta velocidade. Você recebe um ataque desarmado de Focinho que causa 1d6 de dano perfurante com acuidade e mortal d8 (deadly d8).', 'Needle-like snout strikes with fatal precision. You gain a Snout unarmed attack dealing 1d6 piercing with finesse and deadly d8.', 'Hocico alargado y punzante. Obtienes un ataque desarmado de Hocico que causa 1d6 de daño perforante con sutileza y mortal d8.', NULL, '{}'::text[], 'common', 'remaster', 'Uivo da Natureza (Howl of the Wild)', 30, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.athamaru.athamaru_coralino', 'ancestry.athamaru', FALSE, 'Athamaru Coralino', 'Coral Athamaru', 'Athamaru coralino', 'Seu corpo desenvolve placas de exoesqueleto de coral calcificado. Você recebe +1 de bônus circunstancial na CA contra acertos críticos e imunidade a cortes de corais.', 'Calcified coral plating armors your skin. You gain a +1 circumstance bonus to AC against critical hits and ignore coral hazards.', 'Placas de coral calcificado acorazan tu piel. Obtienes un bonificador circunstancial de +1 a la CA contra golpes críticos e ignoras peligros de coral.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Personagens de Tian Xia (Tian Xia Character Guide)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.athamaru.athamaru_esperancoso', 'ancestry.athamaru', FALSE, 'Athamaru Esperançoso', 'Hopeful Athamaru', 'Athamaru esperanzado', 'Sua empatia natural e espírito comunitário encantam aliados e estranhos. Você se torna treinado em Diplomacia e recebe +1 circunstancial para Impressionar.', 'Natural diplomacy and optimism make you a beloved mediator. You become trained in Diplomacy and gain +1 circumstance to Make an Impression.', 'Tu empatía natural te convierte en un hábil mediador. Quedas entrenado en Diplomacia y obtienes +1 circunstancial a Causar buena impresión.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Personagens de Tian Xia (Tian Xia Character Guide)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.athamaru.athamaru_caleidoscopico', 'ancestry.athamaru', FALSE, 'Athamaru Caleidoscópico', 'Kaleidoscopic Athamaru', 'Athamaru caleidoscópico', 'Padrões bioluminescentes brilhantes piscam em suas escamas para deslumbrar inimigos. Você recebe o truque pasmar (daze) como magia inata primal à vontade.', 'Bioluminescent scales flash in mesmerizing patterns. You gain the daze cantrip as an at-will primal innate spell.', 'Escamas bioluminiscentes destellan en patrones hipnóticos. Obtienes el truco atontar como conjuro innato primordial a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Personagens de Tian Xia (Tian Xia Character Guide)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.athamaru.athamaru_espinhoso', 'ancestry.athamaru', FALSE, 'Athamaru Espinhoso', 'Spiny Athamaru', 'Athamaru espinoso', 'Espinhos venenosos recobrem suas nadadeiras e dorso. Criaturas que o atacarem desarmadas sofrem 1d4 de dano perfurante + 1 de dano de veneno.', 'Toxic dorsal spines protect your body. Unarmed attackers take 1d4 piercing damage + 1 poison damage.', 'Espinas venenosas protegen tu cuerpo. Los atacantes desarmados sufren 1d4 de daño perforante + 1 de veneno.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Personagens de Tian Xia (Tian Xia Character Guide)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.surki.surki_rompedor', 'ancestry.surki', FALSE, 'Surki Rompedor', 'Breaker Surki', 'Surki rompedor', 'Mandíbulas maciças escavam terra e rocha compacta. Você recebe deslocamento de escavação de 3 metros (10 pés) em terra e pedra não-mágica.', 'Heavy mandibles chew through earth. You gain a burrow Speed of 10 feet through dirt, sand, and non-magical earth.', 'Mandíbulas pesadas mastigan la roca y la tierra. Obtienes una velocidad de excavación de 3 m (10 pies) en tierra y arena.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Personagens de Tian Xia (Tian Xia Character Guide)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.surki.surki_elitro', 'ancestry.surki', FALSE, 'Surki Élitro', 'Elytra Surki', 'Surki élitro', 'Élitros quitinosos se abrem para amortecer sua descida. Você não sofre dano de quedas de até 15 metros enquanto estiver consciente.', 'Chitinous elytra unfold to slow your fall, taking 0 damage from falls up to 50 feet while conscious.', 'Élitros quitinosos se despliegan para amortiguar tu descenso, sufriendo 0 daño por caídas de hasta 15 m mientras estés consciente.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Personagens de Tian Xia (Tian Xia Character Guide)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.surki.surki_carapaca_dura', 'ancestry.surki', FALSE, 'Surki Carapaça Dura', 'Hard-Carapace Surki', 'Surki caparazón duro', 'Placas minerais cristalinas reforçam seu exoesqueleto. Seus Pontos de Vida de ancestralidade aumentam de 8 para 10 e você recebe +1 circunstancial em testes de Fortitude.', 'Mineralized carapace provides great durability. Your starting ancestry HP increases from 8 to 10 and you gain +1 circumstance to Fortitude saves.', 'Caparazón mineralizado que otorga gran resistencia. Tus PG de ancestro aumentan de 8 a 10 y obtienes +1 circunstancial a Fortaleza.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Personagens de Tian Xia (Tian Xia Character Guide)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.surki.surki_lanterna', 'ancestry.surki', FALSE, 'Surki Lanterna', 'Lantern Surki', 'Surki linterna', 'Órgãos bioluminescentes no abdômen iluminam os túneis subterrâneos. Você pode conjurar luz (light) como magia inata primal à vontade.', 'Abdominal bioluminescent organs cast brilliant light. You can cast the light cantrip as an at-will primal innate spell.', 'Órganos bioluminiscentes iluminan túneles oscuros. Puedes lanzar el truco luz como conjuro innato primordial a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Guia de Personagens de Tian Xia (Tian Xia Character Guide)', 18, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.jotunborn.jotunnato_guardiao', 'ancestry.jotunborn', FALSE, 'Jotunnato Guardião', 'Keeper Jotunborn', 'Jotunnato guardián', 'Você é treinado em Sobrevivência, recebe o talento Rastrear Vida Selvagem e +1 circunstancial para Rastrear animais.', 'You are trained in Survival, gain the Survey Wildlife skill feat, and receive a +1 circumstance bonus to Track animals.', 'Estás entrenado en Supervivencia, obtienes el talento Rastrear fauna y un bonificador circunstancial de +1 para Rastrear animales.', NULL, '{}'::text[], 'common', 'remaster', 'Battlecry! (Remaster)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.jotunborn.jotunnato_salta_planos', 'ancestry.jotunborn', FALSE, 'Jotunnato Salta-Planos', 'Plane-Hopper Jotunborn', 'Jotunnato saltaplanos', 'Seu tamanho é Médio e você recebe um truque da lista ocultista, conjurado como magia inata ocultista à vontade.', 'Your size is Medium, and you gain one occult cantrip cast as an at-will occult innate spell.', 'Tu tamaño es Mediano y obtienes un truco de la lista ocultista, lanzado como conjuro innato ocultista a voluntad.', NULL, '{}'::text[], 'common', 'remaster', 'Battlecry! (Remaster)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.jotunborn.jotunnato_sabio', 'ancestry.jotunborn', FALSE, 'Jotunnato Sábio', 'Sage Jotunborn', 'Jotunnato sabio', 'Você é treinado em Sociedade e recebe o talento geral Conhecimento Adicional para um Saber à sua escolha.', 'You are trained in Society and gain the Additional Lore general feat for a Lore of your choice.', 'Estás entrenado en Sociedad y obtienes el talento general Saber adicional para un Saber de tu elección.', NULL, '{}'::text[], 'common', 'remaster', 'Battlecry! (Remaster)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.jotunborn.jotunnato_guerreiro', 'ancestry.jotunborn', FALSE, 'Jotunnato Guerreiro', 'Warrior Jotunborn', 'Jotunnato guerrero', 'O dado de dano do seu punho aumenta para 1d6 e você não sofre penalidade ao fazer um ataque letal com o punho.', 'Your fist''s damage die increases to 1d6, and you take no penalty for making a lethal attack with your fist.', 'El dado de daño de tu puño aumenta a 1d6 y no sufres penalización por realizar un Golpe letal con el puño.', NULL, '{}'::text[], 'common', 'remaster', 'Battlecry! (Remaster)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ancestry.jotunborn.jotunnato_tecelao', 'ancestry.jotunborn', FALSE, 'Jotunnato Tecelão', 'Weaver Jotunborn', 'Jotunnato tejedor', 'Você é treinado em Manufatura e recebe +1 circunstancial para Perceber ao procurar detalhes ocultos, como portas secretas ou armadilhas.', 'You are trained in Crafting and gain a +1 circumstance bonus to Seek when searching for hidden details such as secret doors or traps.', 'Estás entrenado en Artesanía y obtienes un bonificador circunstancial de +1 a Buscar al buscar detalles ocultos, como puertas secretas o trampas.', NULL, '{}'::text[], 'common', 'remaster', 'Battlecry! (Remaster)', 12, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.nephilim.celestial', NULL, TRUE, 'Nefilim Celestial', 'Celestial Nephilim', 'Nefilim celestial', 'Herança versátil de linhagem celestial ou aasimar.', 'A versatile heritage tied to celestial nephilim ancestry.', 'Una herencia versátil vinculada a la ascendencia nefilim celestial.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 79, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.nephilim.infernal', NULL, TRUE, 'Nefilim Infernal', 'Infernal Nephilim', 'Nefilim infernal', 'Herança versátil de linhagem infernal ou tiefling.', 'A versatile heritage tied to infernal nephilim ancestry.', 'Una herencia versátil vinculada a la ascendencia nefilim infernal.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 79, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.dhampir', NULL, TRUE, 'Dampiro', 'Dhampir', 'Dhampiro', 'Herança versátil mortal conectada à influência vampírica.', 'A mortal versatile heritage connected to vampiric influence.', 'Una herencia versátil mortal conectada con la influencia vampírica.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 44, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.changeling', NULL, TRUE, 'Cambiante', 'Changeling', 'Cambiante', 'Herança versátil ligada à linhagem de uma estriga e à magia ocultista.', 'A versatile heritage tied to changeling ancestry.', 'Una herencia versátil vinculada a la ascendencia cambiante.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 77, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.duskwalker', NULL, TRUE, 'Crepusculante', 'Duskwalker', 'Caminante del ocaso', 'Alma reencarnada ligada aos psicopompos e ao ciclo das almas.', 'A reincarnated soul tied to psychopomps and the cycle of souls.', 'Un alma reencarnada ligada a los psicopompos y al ciclo de las almas.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 42, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.dragonblood', NULL, TRUE, 'Dracano', 'Dragonblood', 'Sangre de dragón', 'Herança versátil de descendência dracônica, com traços físicos ou magia inata.', 'A versatile heritage of draconic descent, with physical traits or innate magic.', 'Una herencia versátil de ascendencia dracónica, con rasgos físicos o magia innata.', NULL, '{}'::text[], 'common', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 46, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ifrit.legacy_pending', NULL, TRUE, 'Ifrit', 'Ifrit', 'Ifrit', 'Herança de fogo que manifesta resistência e afinidade ígnea.', 'A fire heritage that manifests resistance and affinity with flames.', 'Una herencia de fuego que manifiesta resistencia y afinidad con las llamas.', NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.oread.legacy_pending', NULL, TRUE, 'Oread', 'Oread', 'Oread', 'Herança de terra ligada à pedra, minerais e resistência física.', 'An earth heritage tied to stone, minerals, and physical resilience.', 'Una herencia de tierra vinculada a la piedra, los minerales y la resistencia física.', NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.sylph.legacy_pending', NULL, TRUE, 'Sílfide', 'Sylph', 'Sílfide', 'Herança de ar ligada ao vento, mobilidade e respiração livre.', 'An air heritage tied to wind, mobility, and free breathing.', 'Una herencia de aire vinculada al viento, la movilidad y la respiración libre.', NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.undine.legacy_pending', NULL, TRUE, 'Ondina', 'Undine', 'Ondina', 'Herança de água adaptada à natação e a ambientes aquáticos.', 'A water heritage adapted to swimming and aquatic environments.', 'Una herencia de agua adaptada a la natación y los entornos acuáticos.', NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 48, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ardande.legacy_pending', NULL, TRUE, 'Ardande', 'Ardande', 'Ardande', 'Herança vegetal ligada à madeira, crescimento e vida natural.', 'A plant heritage tied to wood, growth, and natural life.', 'Una herencia vegetal vinculada a la madera, el crecimiento y la vida natural.', NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 46, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.talos.legacy_pending', NULL, TRUE, 'Talos', 'Talos', 'Talos', 'Herança metálica ligada a ferro, aço e energia condutiva.', 'A metal heritage tied to iron, steel, and conductive energy.', 'Una herencia metálica vinculada al hierro, el acero y la energía conductora.', NULL, '{}'::text[], 'common', 'remaster', 'Rage of Elements (Remaster)', 50, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.beastkin', NULL, TRUE, 'Beastkin', 'Beastkin', 'Bestial', 'Herança versátil que manifesta uma forma bestial e adaptações de animal.', 'A versatile heritage that manifests a bestial form and animal adaptations.', 'Una herencia versátil que manifiesta una forma bestial y adaptaciones animales.', NULL, '{}'::text[], 'common', 'remaster', 'Howl of the Wild (Remaster, atualização de errata)', 77, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.reflection', NULL, TRUE, 'Reflexo', 'Reflection', 'Reflejo', 'Herança versátil rara para uma duplicata que busca construir identidade própria.', 'A rare versatile heritage for a duplicate seeking to build an identity of their own.', 'Una herencia versátil rara para un duplicado que busca construir una identidad propia.', NULL, '{}'::text[], 'rare', 'legacy', 'Dark Archive (pré-Remaster)', 119, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.ardande', NULL, TRUE, 'Ardande', 'Ardande', 'Ardande', 'Herança versátil geniekin ligada à vitalidade e flexibilidade da madeira elemental.', 'A geniekin versatile heritage tied to the vitality and flexibility of elemental wood.', 'Una herencia versátil geniekin ligada a la vitalidad y flexibilidad de la madera elemental.', NULL, '{}'::text[], 'uncommon', 'remaster', 'Rage of Elements (Remaster)', 46, '{"grants":null,"needs_review":false}'::jsonb),
  ('heritage.talos', NULL, TRUE, 'Talos', 'Talos', 'Talos', 'Herança versátil geniekin conectada ao potencial e à transformação do metal elemental.', 'A geniekin versatile heritage connected to the potential and transformation of elemental metal.', 'Una herencia versátil geniekin conectada con el potencial y la transformación del metal elemental.', NULL, '{}'::text[], 'uncommon', 'remaster', 'Rage of Elements (Remaster)', 50, '{"grants":null,"needs_review":false}'::jsonb)
insert into public.catalog_subclasses (id, class_id, choice_field, name_pt, name_en, name_es, description_pt, description_en, description_es, traits, ruleset, source_book, source_page, data)
values
  ('subclass.class_alchemist_bomber', 'class.alchemist', 'researchField', 'Bombardeiro', 'Bomber', 'Bombardero', 'Especialista em bombas químicas e explosões direcionadas. Você é treinado em Manufatura. Concede fórmulas adicionais de bombas e permite escolher alvos imunes ao dano de espirro de suas bombas.', 'Specialist in chemical bombs and controlled explosions. Trained in Crafting. Grants bonus bomb formulas and lets you choose targets to exclude from splash damage.', 'Especialista en bombas químicas y explosiones dirigidas. Entrenado en Artesanía. Concede fórmulas de bombas y permite evitar el daño por salpicadura a aliados.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 32, '{"trainedSkills":["crafting"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_alchemist_chirurgeon', 'class.alchemist', 'researchField', 'Cirurgião', 'Chirurgeon', 'Cirujano', 'Mestre da anatomia médica, tratamentos cirúrgicos e elixires curativos. Você é treinado em Medicina e Manufatura. Permite usar Manufatura no lugar de Medicina para Primeiros Socorros, Tratar Ferimentos, Tratar Doença e Tratar Veneno.', 'Master of anatomy, surgical procedures, and restorative elixirs. Trained in Medicine and Crafting. Lets you use Crafting in place of Medicine for First Aid, Treat Wounds, Treat Disease, and Treat Poison.', 'Maestro de anatomía y elixires curativos. Entrenado en Medicina y Artesanía. Permite usar Artesanía en lugar de Medicina para Primeros Auxilios, Tratar Heridas, Tratar Enfermedad y Tratar Veneno.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 33, '{"trainedSkills":["medicine","crafting"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_alchemist_mutagenist', 'class.alchemist', 'researchField', 'Mutacionista', 'Mutagenist', 'Mutacionista', 'Especialista em mutagênicos que alteram a fisiologia corporal e mental. Você é treinado em Manufatura. Concede fórmulas de mutagênicos e a capacidade de suprimir penalidades com Surto Mutagênico.', 'Specialist in transmutative mutagens that warp body and mind. Trained in Crafting. Grants mutagen formulas and the ability to mitigate drawbacks with Mutagenic Flash.', 'Especialista en mutágenos que alteran cuerpo y mente. Entrenado en Artesanía. Concede fórmulas de mutágenos y mitiga sus desventajas temporales.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 33, '{"trainedSkills":["crafting"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_alchemist_toxicologist', 'class.alchemist', 'researchField', 'Toxicologista', 'Toxicologist', 'Toxicólogo', 'Mestre de toxinas, venenos e agentes químicos letais. Você é treinado em Manufatura. Concede fórmulas de venenos e permite que seus venenos usem sua CD de classe se for superior à CD base do veneno.', 'Master of toxins, venoms, and lethal biological agents. Trained in Crafting. Grants poison formulas and lets poisons use your class DC if higher than their base DC.', 'Maestro de toxinas y venenos letales. Entrenado en Artesanía. Concede fórmulas de venenos y permite que usen tu CD de clase si es más alta que la CD base.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 34, '{"trainedSkills":["crafting"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_barbarian_instinto_animal', 'class.barbarian', 'instinct', 'Instinto Animal', 'Animal Instinct', 'Instinto Animal', 'Você canaliza o predador interior e a fúria primal de uma besta totêmica. Treinado em Atletismo. Concede ataque desarmado animal exclusivo e bônus de dano de fúria +2 (+5 com Especialização de Arma, +12 Maior).', 'You channel the raw predator spirit and primal fury of a totemic beast. Trained in Athletics. Grants a unique animal unarmed strike and +2 rage damage (+5 with weapon specialization, +12 greater).', 'Canalizas el espíritu depredador y la furia salvaje de una bestia totémica. Entrenado en Atletismo. Concede un ataque desarmado animal exclusivo y +2 al daño de furia (+5 con especialización, +12 mayor).', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 48, '{"trainedSkills":["athletics"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_barbarian_instinto_draconico', 'class.barbarian', 'instinct', 'Instinto Dracônico', 'Dragon Instinct', 'Instinto Dracónico', 'Você canaliza o poder primordial e a respiração ardente dos dragões. Treinado em Intimidação. Concede dano de fúria aumentado (+4 dano, +8 esp., +16 maior) correspondente ao tipo de dragão escolhido e resistência a esse elemento durante a fúria.', 'You channel the primordial might and fiery breath of dragons. Trained in Intimidação. Grants increased rage damage (+4 damage, +8 spec., +16 greater) matching your dragon type and resistance to that element during rage.', 'Canalizas el poder primordial y el aliento abrasador de los dragones. Entrenado en Intimidación. Concede daño de furia aumentado (+4 daño, +8 esp., +16 mayor) del tipo dracónico y resistencia elemental durante la furia.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 49, '{"trainedSkills":["intimidation"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_barbarian_instinto_dos_gigantes', 'class.barbarian', 'instinct', 'Instinto dos Gigantes', 'Giant Instinct', 'Instinto de los Gigantes', 'Você canaliza o poder titânico de gigantes lendários, permitindo empunhar armas de tamanho Grande. Treinado em Atletismo. Concede bônus massivo de dano de fúria (+6 dano, +10 esp., +18 maior), sofrendo a condição Desajeitado 1 durante a fúria.', 'You channel titanic giant strength, enabling you to wield Large weapons. Trained in Athletics. Grants massive rage damage (+6 damage, +10 spec., +18 greater) while suffering Clumsy 1 during rage.', 'Canalizas la fuerza titánica de los gigantes para empuñar armas Grandes. Entrenado en Atletismo. Concede daño masivo de furia (+6 daño, +10 esp., +18 mayor), sufriendo Torpe 1 durante la furia.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 50, '{"trainedSkills":["athletics"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_barbarian_instinto_espiritual', 'class.barbarian', 'instinct', 'Instinto Espiritual', 'Spirit Instinct', 'Instinto Espiritual', 'Guiado por espíritos ancestrais que cercam sua arma de ectoplasma e energia mística. Treinado em Ocultismo ou Religião. Seus golpes durante a fúria causam dano espiritual e afetam criaturas incorpóreas normalmente (+3 dano, +7 esp., +13 maior).', 'Guided by ancestral spirits wreathing your strikes in ethereal force. Trained in Occultism or Religion. Your strikes deal spirit damage during rage and affect incorporeal creatures normally (+3 damage, +7 spec., +13 greater).', 'Guiado por espíritus ancestrales que envuelven tus golpes en fuerza mística. Entrenado en Ocultismo o Religión. Tus golpes infligen daño espiritual durante la furia y afectan a incorpóreos (+3 daño, +7 esp., +13 mayor).', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 50, '{"trainedSkills":["occultism"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_barbarian_instinto_da_furia_elemental', 'class.barbarian', 'instinct', 'Instinto da Fúria Elemental', 'Elemental Fury Instinct', 'Instinto de Furia Elemental', 'Você canaliza o vórtice dos elementos primordiais. Treinado em Natureza. Infunde seus ataques com dano elemental e concede defesas e resistências adaptáveis durante a fúria (+2 dano, +5 esp., +12 maior).', 'You channel the raw storm of primordial elemental planes. Trained in Nature. Infuses your strikes with elemental fury and grants defensive elemental resistances during rage (+2 damage, +5 spec., +12 greater).', 'Canalizas el torbellino de los elementos primordiales. Entrenado en Naturaleza. Infunde tus ataques con daño elemental y otorga resistencias defensivas durante la furia (+2 daño, +5 esp., +12 mayor).', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 51, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_bard_enigma', 'class.bard', 'muse', 'Musa da Erudição', 'Enigma', 'Enigma', 'Inspirado por segredos arcanos, textos esquecidos e enigmas do universo. Você é treinado em Ocultismo e ganha o talento Conhecimento do Bardo (Bardic Lore).', 'Inspired by esoteric mysteries, forgotten texts, and cosmic riddles. Trained in Occultism and gains the Bardic Lore feat.', 'Inspirado por secretos arcanos, textos olvidados y enigmas cósmicos. Entrenado en Ocultismo y obtiene la dote Saber Bárdico.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 96, '{"trainedSkills":["occultism"],"grants":["feat.general.bardic_lore"],"needs_review":false}'::jsonb),
  ('subclass.class_bard_maestro', 'class.bard', 'muse', 'Musa da Coragem', 'Maestro', 'Maestro', 'Virtuoso da oratória e composições heroicas que inflamam o espírito de batalha. Você é treinado em Atuação e ganha o talento Canção Persistente (Lingering Composition).', 'Virtuoso of rousing oratory and heroic compositions that ignite warriors'' spirits. Trained in Performance and gains the Lingering Composition feat.', 'Virtuoso de la oratoria y composiciones heroicas que encienden el espíritu de combate. Entrenado en Interpretación y obtiene la dote Composición Persistente.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 97, '{"trainedSkills":["performance"],"grants":["feat.general.lingering_composition"],"needs_review":false}'::jsonb),
  ('subclass.class_bard_warrior', 'class.bard', 'muse', 'Musa da Lâmina', 'Warrior', 'Guerrero', 'Skald de guerra que luta nas primeiras fileiras entoando cantos marciais. Você é treinado em Atletismo, em armas marciais e ganha o talento Balada Marcial.', 'Frontline battle-skald chanting war songs in close combat. Trained in Athletics, martial weapons, and gains the Martial Performance feat.', 'Skald de batalla que lucha en primera línea entonando cantos bélicos. Entrenado en Atletismo, armas marciales y obtiene la dote Interpretación Marcial.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 97, '{"trainedSkills":["athletics"],"grants":["feat.general.martial_performance"],"needs_review":false}'::jsonb),
  ('subclass.class_bard_polymath', 'class.bard', 'muse', 'Musa da Polifonia', 'Polymath', 'Polifacético', 'Artista eclético que domina múltiplos estilos, disfarces e instrumentos. Você é treinado em Enganação e ganha o talento Atuação Versátil (Versatile Performance) para usar Atuação em testes de diplomacia e intimidação.', 'Eclectic performer mastering varied genres, disguise, and versatility. Trained in Deception and gains the Versatile Performance feat to use Performance for social checks.', 'Artista ecléctico que domina múltiples disciplinas e instrumentos. Entrenado en Engaño y obtiene la dote Interpretación Versátil para usar Interpretación en pruebas sociales.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 98, '{"trainedSkills":["deception"],"grants":["feat.general.versatile_performance"],"needs_review":false}'::jsonb),
  ('subclass.class.witch.patron_faiths_flamekeeper', 'class.witch', 'patron', 'Guardião da Fé Irrefreável', 'Faith''s Flamekeeper', 'Guardián de la Fe Inquebrantable', 'Patrono de Bruxa da tradição divine; concede Avivar o Coração e Familiar do Espírito Restaurado.', 'Witch patron of the divine tradition; grants Stoke the Heart and Familiar of Restored Spirit.', 'Patrón de Bruja de tradición divine; concede Avivar el Corazón y Familiar del Espíritu Restaurado.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 114, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.witch.patron_wilding_steward', 'class.witch', 'patron', 'Sentinela dos Ermos', 'Wilding Steward', 'Guardián de las Tierras Salvajes', 'Patrono de Bruxa da tradição primal; concede Palavra dos Ermos e Familiar dos Sentidos Aguçados.', 'Witch patron of the primal tradition; grants Wilding Word and Familiar of Keen Senses.', 'Patrón de Bruja de tradición primal; concede Palabra Salvaje y Familiar de Sentidos Agudos.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 114, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.witch.patron_the_inscribed_one', 'class.witch', 'patron', 'O Inscrito', 'The Inscribed One', 'El Inscrito', 'Patrono de Bruxa da tradição arcane; concede Discernir Segredos e Familiar da Escrita Fluida.', 'Witch patron of the arcane tradition; grants Discern Secrets and Familiar of Flowing Script.', 'Patrón de Bruja de tradición arcane; concede Discernir Secretos y Familiar de Escritura Fluida.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 114, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.witch.patron_the_resentment', 'class.witch', 'patron', 'O Ressentimento', 'The Resentment', 'El Resentimiento', 'Patrono de Bruxa da tradição occult; concede Mau-Olhado e Familiar da Miséria Persistente.', 'Witch patron of the occult tradition; grants Evil Eye and Familiar of Ongoing Misery.', 'Patrón de Bruja de tradición occult; concede Mal de Ojo y Familiar de la Miseria Persistente.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 115, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.witch.patron_spinner_of_threads', 'class.witch', 'patron', 'O Tecelão de Destinos', 'Spinner of Threads', 'Tejedor de Destinos', 'Patrono de Bruxa da tradição occult; concede Tocar o Destino e Familiar da Sorte Equilibrada.', 'Witch patron of the occult tradition; grants Nudge Fate and Familiar of Balanced Luck.', 'Patrón de Bruja de tradición occult; concede Tocar el Destino y Familiar de la Suerte Equilibrada.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 115, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.witch.patron_silence_in_snow', 'class.witch', 'patron', 'O Silêncio Invernal', 'Silence in Snow', 'Silencio Invernal', 'Patrono de Bruxa da tradição primal; concede Gelo Duradouro e Familiar da Geada Congelante.', 'Witch patron of the primal tradition; grants Clinging Ice and Familiar of Freezing Rime.', 'Patrón de Bruja de tradición primal; concede Hielo Persistente y Familiar de Escarcha Helada.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 115, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.witch.patron_starless_shadow', 'class.witch', 'patron', 'A Sombra Inconstelada', 'Starless Shadow', 'Sombra sin Estrellas', 'Patrono de Bruxa da tradição occult; concede Mortalha da Noite e Familiar da Noite que Espreita.', 'Witch patron of the occult tradition; grants Shroud of Night and Familiar of Stalking Night.', 'Patrón de Bruja de tradición occult; concede Sudario de la Noche y Familiar de la Noche Acechante.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 115, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_champion_retribuicao', 'class.champion', 'cause', 'Paladino (Retribuição)', 'Paladin (Retributive Strike)', 'Paladín (Golpe Retributivo)', 'Campeão da justiça inflexível e virtude sacra. Concede a reação Golpe Retributivo (Retributive Strike) para proteger aliados e golpear imediatamente o agressor.', 'Champion of righteous justice. Grants the Retributive Strike reaction to protect allies and punish aggressors immediately.', 'Campeón de la justicia implacable. Concede la reacción Golpe Retributivo para proteger aliados y contraatacar agresores.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 58, '{"trainedSkills":["religion"],"grants":["action.retributive_strike"],"needs_review":false}'::jsonb),
  ('subclass.class_champion_misericordia', 'class.champion', 'cause', 'Redentor (Misericórdia)', 'Redeemer (Glimpse of Redemption)', 'Redentor (Atisbo de Redención)', 'Campeão da compaixão e redenção. Concede a reação Vislumbre da Redenção para oferecer ao agressor a escolha de poupar o dano ou sofrer penalidades paralisantes.', 'Champion of mercy and forgiveness. Grants Glimpse of Redemption reaction offering foes a choice between mercy or debilitating penalties.', 'Campeón de la compasión y el perdón. Concede la reacción Atisbo de Redención ofreciendo piedad o penalizaciones graves.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 59, '{"trainedSkills":["religion"],"grants":["action.glimpse_of_redemption"],"needs_review":false}'::jsonb),
  ('subclass.class_champion_liberdade', 'class.champion', 'cause', 'Libertador (Liberdade)', 'Liberator (Liberating Step)', 'Libertador (Paso Liberador)', 'Campeão da autonomia e liberdade contra grilhões. Concede a reação Passo Libertador para reduzir dano a aliados e permitir fuga de agarramentos e efeitos restritivos.', 'Champion of freedom and liberation. Grants Liberating Step reaction to mitigate ally damage and grant immediate escape from grabs and restraints.', 'Campeón de la libertad y autonomía. Concede la reacción Paso Liberador para reducir daño a aliados y permitir escape inmediato de agarres.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 59, '{"trainedSkills":["religion"],"grants":["action.liberating_step"],"needs_review":false}'::jsonb),
  ('subclass.class_champion_tiranos_desesperadores', 'class.champion', 'cause', 'Profano (Tiranos/Desesperadores)', 'Unholy Champion (Tyrant / Desecrator)', 'Profano (Tirano / Profanador)', 'Campeão profano que subjuga oponentes com opressão de ferro, dor implacável e destruição dos inocentes.', 'Unholy champion subjugating foes through iron oppression, agonizing retribution, and destructive fury.', 'Campeón profano que subyuga enemigos mediante opresión despiadada y dolor retributivo.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 60, '{"trainedSkills":["intimidation"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_kineticist_elemento_do_fogo', 'class.kineticist', 'elementalGate', 'Elemento do Fogo', 'Fire Element', 'Elemento del Fuego', 'Canalização de calor escaldante, labaredas destruidoras e auras de combustão incandescente.', 'Channeling intense scouring heat, blazing explosions, and searing combustion auras.', 'Canalización de calor abrasador, llamas devastadoras y auras de combustión incandescente.', '{}'::text[], 'remaster', 'Fúria dos Elementos (Rage of Elements)', 14, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_kineticist_elemento_da_agua', 'class.kineticist', 'elementalGate', 'Elemento da Água', 'Water Element', 'Elemento del Agua', 'Canalização de marés purificadoras, jatos de alta pressão e restauração vital fluida.', 'Channeling surging tides, pressurized currents, and revitalizing waves.', 'Canalización de mareas purificadoras, torrentes a presión y restauración vital.', '{}'::text[], 'remaster', 'Fúria dos Elementos (Rage of Elements)', 15, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_kineticist_elemento_da_terra', 'class.kineticist', 'elementalGate', 'Elemento da Terra', 'Earth Element', 'Elemento de la Tierra', 'Canalização de rochas maciças, armaduras geológicas e muralhas de pedra protetoras.', 'Channeling dense stone, geologic armor, and earthen bulwarks.', 'Canalización de rocas macizas, armaduras geológicas y murallas de piedra.', '{}'::text[], 'remaster', 'Fúria dos Elementos (Rage of Elements)', 16, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_kineticist_elemento_do_ar', 'class.kineticist', 'elementalGate', 'Elemento do Ar', 'Air Element', 'Elemento del Aire', 'Canalização de brisas velozes, lufadas ciclônicas, voo e mobilidade aérea superior.', 'Channeling swift gales, cyclonic gusts, flight, and unmatched mobility.', 'Canalización de vendavales veloces, ráfagas ciclónicas, vuelo y movilidad aérea.', '{}'::text[], 'remaster', 'Fúria dos Elementos (Rage of Elements)', 17, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_kineticist_elemento_da_madeira', 'class.kineticist', 'elementalGate', 'Elemento da Madeira', 'Wood Element', 'Elemento de la Madera', 'Canalização de crescimento vegetal acelerado, barreiras de espinhos e vitalidade florescente.', 'Channeling rapid plant growth, thorny barriers, and flourishing vitality.', 'Canalización de crecimiento vegetal acelerado, barreras de espinas y vitalidad floreciente.', '{}'::text[], 'remaster', 'Fúria dos Elementos (Rage of Elements)', 18, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_kineticist_elemento_do_metal', 'class.kineticist', 'elementalGate', 'Elemento do Metal', 'Metal Element', 'Elemento del Metal', 'Canalização de ligas metálicas afiadas, condutividade magnética e lâminas forjadas de ferro.', 'Channeling razor metal alloys, magnetic conductivity, and forged iron blades.', 'Canalización de aleaciones metálicas afiladas, magnetismo y armas forjadas.', '{}'::text[], 'remaster', 'Fúria dos Elementos (Rage of Elements)', 19, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_kineticist_portao_duplo', 'class.kineticist', 'elementalGate', 'Portão Duplo', 'Dual Gate', 'Puerta Doble', 'Abertura sinérgica para dois elementos combinados em harmonia elemental simultânea.', 'Synergistic channel opening two distinct elements in blended harmony.', 'Apertura sinérgica a dos elementos combinados en armonía simultánea.', '{}'::text[], 'remaster', 'Fúria dos Elementos (Rage of Elements)', 20, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_cleric_cloistered', 'class.cleric', 'doctrine', 'Doutrina de Conjurador Enclausurado', 'Cloistered Cleric', 'Clérigo Claustrado', 'Foco devoto na oração, liturgia e conjuração divina. Você é treinado em Religião e na perícia da divindade. Concede o talento Iniciado do Domínio (Domain Initiate), salvaguardas de Vontade Especialistas no 1º nível e progressão acelerada de CD de magia divina.', 'Devoted focus on sacred liturgy and divine spellcasting. Trained in Religion and deity skill. Grants the Domain Initiate feat, Expert Will saves at 1st level, and accelerated spell DC progression.', 'Enfoque devoto en la liturgia sagrada y la magia divina. Entrenado en Religión y la habilidad de la deidad. Concede la dote Iniciado del Dominio, salvaciones de Voluntad Experto a nivel 1 y progresión acelerada de CD divina.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 110, '{"trainedSkills":["religion"],"grants":["feat.general.domain_initiate"],"needs_review":false}'::jsonb),
  ('subclass.class_cleric_warpriest', 'class.cleric', 'doctrine', 'Doutrina de Clérigo de Guerra', 'Warpriest', 'Clérigo de Guerra', 'Combatente sagrado blindado que empunha a arma favorita da divindade em batalha. Treinado em armaduras leves e médias, na arma da divindade, ganha o talento Bloqueio com Escudo (Shield Block) e salvaguardas de Fortitude Especialistas no 1º nível.', 'Armored holy combatant wielding the deity''s favored weapon in battle. Trained in light and medium armor, deity''s weapon, gains Shield Block feat and Expert Fortitude saves at 1st level.', 'Combatiente sagrado acorazado con el arma predilecta de la deidad. Entrenado en armaduras ligeras e intermedias, arma de la deidad, obtiene Bloqueo con Escudo y salvaciones de Fortaleza Experto a nivel 1.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 111, '{"trainedSkills":["religion"],"grants":["feat.general.shield_block"],"needs_review":false}'::jsonb),
  ('subclass.class_summoner_eidolon_dragao', 'class.summoner', 'eidolon', 'Eidolon Dragão', 'Dragon Eidolon', 'Eidolon Dragón', 'Eidolon reptiliano dracônico ligado à tradição arcana com garras afiadas, escamas duras e sopro elemental.', 'Reptilian draconic eidolon bound to the arcane tradition with breath weapon and hardened scales.', 'Eidolon reptiliano vinculado a la tradición arcana con arma de aliento y escamas protectoras.', '{}'::text[], 'remaster', 'Segredos da Magia (Secrets of Magic)', 54, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_summoner_eidolon_fera', 'class.summoner', 'eidolon', 'Eidolon Fera', 'Beast Eidolon', 'Eidolon Bestia', 'Eidolon predatório selvagem ligado à tradição primal com sentidos aguçados e fúria bestial.', 'Primal predator eidolon bound to nature with acute senses and ferocious attacks.', 'Eidolon depredador vinculado a la tradición primigenia con sentidos agudos y furia salvaje.', '{}'::text[], 'remaster', 'Segredos da Magia (Secrets of Magic)', 55, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_summoner_eidolon_anjo', 'class.summoner', 'eidolon', 'Eidolon Anjo', 'Angel Eidolon', 'Eidolon Ángel', 'Eidolon celestial radiante ligado à tradição divina com bênçãos luminosas e cura sagrada.', 'Celestial angel eidolon bound to the divine tradition with radiant aura and holy blessings.', 'Eidolon celestial vinculado a la tradición divina con aura radiante y bendiciones sagradas.', '{}'::text[], 'remaster', 'Segredos da Magia (Secrets of Magic)', 56, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_summoner_eidolon_demonio', 'class.summoner', 'eidolon', 'Eidolon Demônio', 'Demon Eidolon', 'Eidolon Demonio', 'Eidolon abissal corruptor ligado à tradição divina com pecados contagiosos e ataques profanos.', 'Abyssal demon eidolon bound to divine tradition with corrosive sin and unholy fury.', 'Eidolon demoníaco vinculado a la tradición divina con pecados y ataques profanos.', '{}'::text[], 'remaster', 'Segredos da Magia (Secrets of Magic)', 57, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_summoner_eidolon_fantasma', 'class.summoner', 'eidolon', 'Eidolon Fantasma', 'Phantom Eidolon', 'Eidolon Fantasma', 'Eidolon espectral ligado à tradição oculta que transita entre o plano material e o plano etéreo.', 'Spectral spirit eidolon bound to the occult tradition phasing across ethereal space.', 'Eidolon espiritual vinculado a la tradición oculta que transita por el plano etéreo.', '{}'::text[], 'remaster', 'Segredos da Magia (Secrets of Magic)', 58, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_summoner_eidolon_elemental', 'class.summoner', 'eidolon', 'Eidolon Elemental', 'Elemental Eidolon', 'Eidolon Elemental', 'Eidolon primordial de terra, fogo, água ou ar canalizado diretamente dos planos elementais.', 'Primordial elemental eidolon of earth, fire, water, or air from the inner planes.', 'Eidolon primordial de tierra, fuego, agua o aire canalizado de los planos elementales.', '{}'::text[], 'remaster', 'Segredos da Magia (Secrets of Magic)', 59, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_druid_ordem_dos_animais', 'class.druid', 'order', 'Ordem dos Animais', 'Animal Order', 'Orden Animal', 'Ligado intimamente aos animais da natureza. Você é treinado em Atletismo. Concede o talento Companheiro Animal (Animal Companion) e a magia de ordem Curar Animal (Heal Animal).', 'Deeply bonded with the beasts of nature. Trained in Athletics. Grants the Animal Companion feat and the Heal Animal order focus spell.', 'Profundamente vinculado con las bestias de la naturaleza. Entrenado en Atletismo. Concede la dote Compañero Animal y el conjuro de orden Sanar Animal.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 128, '{"trainedSkills":["athletics"],"grants":["feat.general.animal_companion"],"needs_review":false}'::jsonb),
  ('subclass.class_druid_ordem_das_folhas', 'class.druid', 'order', 'Ordem das Folhas', 'Leaf Order', 'Orden de las Hojas', 'Protetor das florestas, plantas e espíritos vegetais. Você é treinado em Diplomacia. Concede um Familiar Lésico e a magia de ordem Bagas Boas (Goodberry / Cornucopia).', 'Protector of ancient forests and plant spirits. Trained in Diplomacy. Grants a Leshy Familiar and the Goodberry/Cornucopia order focus spell.', 'Protector de bosques y espíritus vegetales. Entrenado en Diplomacia. Concede un Familiar Leshy y el conjuro de orden Bayas Buenas.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 129, '{"trainedSkills":["diplomacy"],"grants":["feat.general.leshy_familiar"],"needs_review":false}'::jsonb),
  ('subclass.class_druid_ordem_das_tempestades', 'class.druid', 'order', 'Ordem das Tempestades', 'Storm Order', 'Orden de la Tormenta', 'Canaliza a fúria dos ventos tempestuosos e relâmpagos primais. Você é treinado em Acrobacia. Concede o talento Nascido da Tempestade e a magia de foco Raio da Tempestade (Tempest Surge).', 'Channels howling gale winds and lightning storms. Trained in Acrobatics. Grants the Storm Born feat and the Tempest Surge focus spell.', 'Canaliza la furia de los vientos y relámpagos primordiales. Entrenado en Acrobacias. Concede Nacido de la Tormenta y el conjuro Oleada Tempestuosa.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 129, '{"trainedSkills":["acrobatics"],"grants":["feat.general.storm_born"],"needs_review":false}'::jsonb),
  ('subclass.class_druid_wild', 'class.druid', 'order', 'Ordem dos Metamorfos', 'Wild Order (Untamed)', 'Orden Salvaje', 'Mestre da transmutação física primal em predadores e monstros. Você é treinado em Intimidação. Concede o talento Forma Indomada (Untamed Form / Wild Shape) e magias de foco de metamorfose.', 'Master of shapeshifting into primal predators and beasts. Trained in Intimidation. Grants the Untamed Form feat and focus shapeshifting spells.', 'Maestro del cambio de forma en depredadores y bestias primigenias. Entrenado en Intimidación. Concede la dote Forma Salvaje y conjuros de metamorfosis.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 130, '{"trainedSkills":["intimidation"],"grants":["feat.general.wild_shape"],"needs_review":false}'::jsonb),
  ('subclass.class_druid_ordem_das_ondas', 'class.druid', 'order', 'Ordem das Ondas', 'Wave Order', 'Orden de las Olas', 'Domina a fluidez de rios, oceanos e marés turbulentas. Você é treinado em Natureza e Atletismo. Concede magias aquáticas e deslocamento na água.', 'Masters fluid tides, surging rivers, and deep seas. Trained in Nature and Athletics. Grants aquatic spells and fluid water movement.', 'Domina mareas, ríos y océanos profundos. Entrenado en Naturaleza y Atletismo. Concede conjuros acuáticos y desplazamiento fluido.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 130, '{"trainedSkills":["nature","athletics"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_swashbuckler_fencer', 'class.swashbuckler', 'style', 'Esgrimista', 'Fencer', 'Esgrimista', 'Você confia em fintas, truques e distrações rápidas para abrir brechas na guarda do inimigo. Você é treinado em Enganação. Você ganha Panache sempre que Fintar (Feint) ou Criar uma Distração (Create a Diversion) com sucesso contra um oponente em combate.', 'You rely on feints, tricks, and quick misdirection to bypass enemy guard. You are trained in Deception. You gain panache whenever you successfully Feint or Create a Diversion against a foe in combat.', 'Confías en fintas, trucos y distracciones rápidas para superar la guardia enemiga. Estás entrenado en Engaño. Obtienes garbo siempre que fintar o crear una distracción con éxito contra un oponente en combate.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 100, '{"trainedSkills":["deception"],"grants":["action.feint","action.create_a_diversion"],"needs_review":false}'::jsonb),
  ('subclass.class_swashbuckler_wit', 'class.swashbuckler', 'style', 'Mordaz', 'Wit', 'Mordaz', 'Você desarma seus oponentes com tiradas afiadas, provocações perspicazes e piadas mordazes. Você é treinado em Diplomacia e ganha o talento Farpas (Bon Mot). Você ganha Panache sempre que usar Farpas com sucesso contra um adversário.', 'You disarm foes with sharp quips, clever banter, and biting wit. You are trained in Diplomacy and gain the Bon Mot feat. You gain panache whenever you successfully use Bon Mot against a foe.', 'Desarmas a tus oponentes con réplicas agudas, provocaciones ingeniosas y comentarios mordaces. Estás entrenado en Diplomacia y obtienes la dote Bon Mot. Obtienes garbo siempre que uses Bon Mot con éxito contra un adversario.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 101, '{"trainedSkills":["diplomacy"],"grants":["feat.general.bon_mot"],"needs_review":false}'::jsonb),
  ('subclass.class_swashbuckler_braggart', 'class.swashbuckler', 'style', 'Fanfarrão', 'Braggart', 'Fanfarrón', 'Você domina o campo de batalha gabando-se abertamente e aterrorizando inimigos com bravatas e presença imponente. Você é treinado em Intimidação. Você ganha Panache sempre que Desmoralizar (Demoralize) com sucesso contra um oponente.', 'You command the battlefield with boastful swagger and overwhelming bravado. You are trained in Intimidation. You gain panache whenever you successfully Demoralize a foe.', 'Dominas el campo de batalla con fanfarronería y presencia imponente. Estás entrenado en Intimidación. Obtienes garbo siempre que desmoralices con éxito a un enemigo.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 100, '{"trainedSkills":["intimidation"],"grants":["action.demoralize"],"needs_review":false}'::jsonb),
  ('subclass.class_swashbuckler_battledancer', 'class.swashbuckler', 'style', 'Audaz', 'Battledancer', 'Bailarín de Batalla', 'Você transforma a luta em uma coreografia deslumbrante e hipnotizante. Você é treinado em Atuação e ganha o talento Dança Fascinante (Fascinating Performance). Você ganha Panache ao Atuar em combate com sucesso para fascinar ou desorientar adversários.', 'You turn melee combat into a mesmerizing, acrobatic choreography. You are trained in Performance and gain the Fascinating Performance feat. You gain panache whenever you successfully Perform in combat to mesmerize foes.', 'Conviertes la lucha en una coreografía deslumbrante e hipnótica. Estás entrenado en Interpretación y obtienes la dote Interpretación Fascinante. Obtienes garbo cuando actúas con éxito en combate para fascinar adversarios.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 100, '{"trainedSkills":["performance"],"grants":["feat.general.fascinating_performance"],"needs_review":false}'::jsonb),
  ('subclass.class_swashbuckler_gymnast', 'class.swashbuckler', 'style', 'Ginasta', 'Gymnast', 'Gimnasta', 'Você domina o combate através de força muscular explosiva, alavancagens e agilidade física. Você é treinado em Atletismo. Você ganha Panache sempre que Agarrar (Grapple), Derrubar (Trip) ou Empurrar (Shove) com sucesso contra um oponente.', 'You dominate combat with explosive athleticism, physical leverage, and acrobatics. You are trained in Athletics. You gain panache whenever you successfully Grapple, Trip, or Shove a foe.', 'Dominas el combate con fuerza atlética explosiva, palanca y agilidad física. Estás entrenado en Atletismo. Obtienes garbo siempre que agarras, derribas o empujas con éxito a un enemigo.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 101, '{"trainedSkills":["athletics"],"grants":["action.grapple","action.trip","action.shove"],"needs_review":false}'::jsonb),
  ('subclass.class_sorcerer_linhagem_draconica', 'class.sorcerer', 'bloodline', 'Linhagem Dracônica', 'Draconic Bloodline', 'Linaje Dracónico', 'O sangue ardente dos dragões corre em suas veias. Tradição Arcana. Treinado em Arcanismo. Concede garras de dragão e magias de sopro destrutivo.', 'Draconic fire surges through your veins. Arcane tradition. Trained in Arcana. Grants dragon claws and destructive breath spells.', 'La sangre ardiente de los dragones corre por tus venas. Tradición Arcana. Entrenado en Arcanos. Concede garras y aliento de dragón.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 132, '{"trainedSkills":["arcana"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_sorcerer_linhagem_feerica', 'class.sorcerer', 'bloodline', 'Linhagem Feérica', 'Fey Bloodline', 'Linaje Feérico', 'O capricho e o glamour do Primeiro Mundo moldam suas magias. Tradição Primal. Treinado em Natureza. Concede magias de glamour, ilusão e encantamento.', 'Whimsical glamour of the First World shapes your magic. Primal tradition. Trained in Nature. Grants glamour, illusion, and enchantment spells.', 'El capricho del Primer Mundo moldea tus conjuros. Tradición Primigenia. Entrenado en Naturaleza. Concede conjuros de ilusión y encantamiento.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 133, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_sorcerer_linhagem_angelica', 'class.sorcerer', 'bloodline', 'Linhagem Angélica', 'Angelic Bloodline', 'Linaje Angélico', 'A graça celestial dos reinos sagrados abençoa suas palavras. Tradição Divina. Treinado em Religião. Concede magias de cura angelical e halo radiante protetor.', 'Celestial grace and holy radiance bless your spellcasting. Divine tradition. Trained in Religion. Grants angelic healing and protective radiant halos.', 'La gracia celestial bendice tus conjuros. Tradición Divina. Entrenado en Religión. Concede conjuros de curación celestial y halo radiante.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 132, '{"trainedSkills":["religion"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_sorcerer_linhagem_demoniaca', 'class.sorcerer', 'bloodline', 'Linhagem Demoníaca', 'Demonic Bloodline', 'Linaje Demoníaco', 'O caos corruptor do Abismo ferve em sua alma. Tradição Divina. Treinado em Intimidação. Concede magias de destruição, fúria e punição profana.', 'Corruptive Abyssal chaos boils within your blood. Divine tradition. Trained in Intimidation. Grants spells of unholy fury and destruction.', 'El caos corruptor del Abismo bulle en tu sangre. Tradición Divina. Entrenado en Intimidación. Concede conjuros de destrucción y furia profana.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 133, '{"trainedSkills":["intimidation"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_sorcerer_linhagem_aberrante', 'class.sorcerer', 'bloodline', 'Linhagem Aberrante', 'Aberrant Bloodline', 'Linaje Aberrante', 'Horrores alienígenas da Tapeçaria Escura ecoam em sua mente. Tradição Oculta. Treinado em Ocultismo. Concede tentáculos psíquicos e magias de loucura cósmica.', 'Alien cosmic horrors and the Dark Tapestry whisper to you. Occult tradition. Trained in Occultism. Grants tentacle strikes and maddening spells.', 'Horrores cósmicos alienígenas susurran en tu mente. Tradición Oculta. Entrenado en Ocultismo. Concede tentáculos psíquicos y conjuros de locura.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 132, '{"trainedSkills":["occultism"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_sorcerer_linhagem_elemental', 'class.sorcerer', 'bloodline', 'Linhagem Elemental', 'Elemental Bloodline', 'Linaje Elemental', 'A força primordial dos planos elementais pulsa em seu corpo. Tradição Primal. Treinado em Natureza. Concede explosões elementais e resistências.', 'Raw primordial force of the elemental planes. Primal tradition. Trained in Nature. Grants elemental blasts and elemental resistances.', 'Fuerza primordial de los planos elementales. Tradición Primigenia. Entrenado en Naturaleza. Concede ráfagas elementales y resistencias.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 133, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_sorcerer_linhagem_imperial', 'class.sorcerer', 'bloodline', 'Linhagem Imperial', 'Imperial Bloodline', 'Linaje Imperial', 'Descendente de uma linhagem de antigos arquimagos e dinastias lendárias. Tradição Arcana. Treinado em Sociedade. Concede magias de autoridade e recuperação mágica.', 'Descendant of ancient mortal archmages and dynastic rulers. Arcane tradition. Trained in Society. Grants spells of magical authority and recovery.', 'Descendiente de antiguos archimagos legendarios. Tradición Arcana. Entrenado en Sociedad. Concede conjuros de autoridad mágica.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 134, '{"trainedSkills":["society"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_fighter_estilo_de_arma_dupla', 'class.fighter', NULL, 'Estilo de Arma Dupla', 'Dual-Weapon Style', 'Estilo de Arma Doble', 'Especialista em empunhar duas armas simultaneamente para desferir ataques coordenados, fintas rápidas e defesas cruzadas.', 'Master of wielding twin weapons simultaneously for coordinated strikes, quick feints, and cross-parries.', 'Maestro en empuñar dos armas simultáneamente para ataques coordinados y bloqueos defensivos.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 138, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_fighter_estilo_de_escudo_e_lamina', 'class.fighter', NULL, 'Estilo de Escudo e Lâmina', 'Shield and Blade Style', 'Estilo de Escudo y Hoja', 'Guerreiro clássico equilibrando proteção de escudo pesado e golpes precisos de arma de uma mão.', 'Classic warrior balancing heavy shield protection with precise one-handed weapon strikes.', 'Guerrero clásico que equilibra la protección del escudo con golpes precisos de arma a una mano.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 139, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_fighter_estilo_de_arma_de_duas_maos', 'class.fighter', NULL, 'Estilo de Arma de Duas Mãos', 'Two-Handed Weapon Style', 'Estilo de Arma a Dos Manos', 'Guerreiro que utiliza alavancagem máxima e armas pesadas de duas mãos para desferir golpes devastadores.', 'Warrior utilizing maximum leverage and heavy two-handed weapons for devastating blows.', 'Guerrero que utiliza el máximo apalancamiento y armas a dos manos para golpes demoledores.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 139, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_fighter_estilo_arqueiro', 'class.fighter', NULL, 'Estilo Arqueiro', 'Archer Style', 'Estilo Arquero', 'Mestre de pontaria à distância com arcos e bestas, disparando múltiplos projéteis com extrema precisão.', 'Master marksman with bows and crossbows, delivering rapid volleys with extreme precision.', 'Maestro tirador con arcos y ballestas, disparando salvas con extrema precisión.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 139, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_fighter_estilo_mao_livre', 'class.fighter', NULL, 'Estilo Mão Livre', 'Free-Hand Style', 'Estilo Mano Libre', 'Lutador ágil com uma mão livre para agarrar, desarmar, usar itens e executar manobras atléticas de duelo.', 'Agile duelist keeping one hand free to grapple, trip, use items, and perform athletic maneuvers.', 'Duelista ágil con una mano libre para agarrar, desarmar, usar objetos y ejecutar maniobras.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 140, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_investigator_metodologia_alquimica', 'class.investigator', 'methodology', 'Metodologia Alquímica', 'Alchemical Sciences', 'Ciencias Alquímicas', 'Aplica reagentes e química investigativa no trabalho de campo. Treinado em Manufatura. Concede o talento Manufatura Alquímica e tinturas rápidas diárias de elixires e ferramentas.', 'Applies chemical science and forensics to investigative cases. Trained in Crafting. Grants Alchemical Crafting and daily versatile alchemical tinctures.', 'Aplica química y ciencias forenses a la investigación. Entrenado en Artesanía. Concede Artesanía Alquímica y tinturas versátiles diarias.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 84, '{"trainedSkills":["crafting"],"grants":["feat.general.alchemical_crafting"],"needs_review":false}'::jsonb),
  ('subclass.class_investigator_metodologia_forense', 'class.investigator', 'methodology', 'Metodologia Forense', 'Forensic Medicine', 'Medicina Forense', 'Especialista em autópsias, análise corporal e cirurgia de campo. Treinado em Medicina. Concede o talento Medicina de Batalha (Battle Medicine), restaura pontos de vida adicionais e reduz a imunidade do alvo para 1 hora.', 'Specialist in anatomy, autopsy, and surgical first response. Trained in Medicine. Grants Battle Medicine, restores additional HP, and reduces target immunity to 1 hour.', 'Especialista en autopsias, anatomía y medicina de emergencia. Entrenado en Medicina. Concede Medicina de Batalla, restaura PG adicionales y reduce la inmunidad a 1 hora.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 85, '{"trainedSkills":["medicine"],"grants":["feat.general.battle_medicine"],"needs_review":false}'::jsonb),
  ('subclass.class_investigator_metodologia_interrogatoria', 'class.investigator', 'methodology', 'Metodologia Interrogatória', 'Interrogation', 'Interrogatorio', 'Mestre em interrogatórios psicológicos e leitura de testemunhas. Treinado em Diplomacia. Concede a ação Pergunta Direta (Pointed Question) para desestabilizar suspeitos em diálogo ou combate.', 'Master of psychological questioning and witness assessment. Trained in Diplomacy. Grants Pointed Question to rattle suspects in dialogue or combat.', 'Maestro del interrogatorio y lectura de testigos. Entrenado en Diplomacia. Concede Pregunta Incisiva para desestabilizar sospechosos en diálogo o combate.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 85, '{"trainedSkills":["diplomacy"],"grants":["action.pointed_question"],"needs_review":false}'::jsonb),
  ('subclass.class_investigator_metodologia_empirica', 'class.investigator', 'methodology', 'Metodologia Empírica', 'Empiricism', 'Empirismo', 'Observador minucioso de evidências físicas e detalhes ocultos. Treinado em Sociedade. Concede a habilidade Isso é Estranho (That''s Odd) para notar pistas e discrepâncias instantaneamente.', 'Meticulous observer of physical clues and logical deduction. Trained in Society. Grants That''s Odd to spot hidden inconsistencies in any scene instantly.', 'Observador minucioso de pistas físicas y lógica. Entrenado en Sociedad. Concede ¡Qué Raro! para detectar inconsistencias ocultas al instante.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 86, '{"trainedSkills":["society"],"grants":["action.thats_odd"],"needs_review":false}'::jsonb),
  ('subclass.class_inventor_inovacao_de_armadura', 'class.inventor', 'innovation', 'Inovação de Armadura', 'Armor Innovation', 'Innovación de Armadura', 'Traje mecânico customizado com blindagem reforçada, impulsores de velocidade, camuflagem ou módulos defensivos avançados.', 'Customized suit of powered or mechanical armor modified with reinforced plating, speed thrusters, or stealth camouflage.', 'Armadura mecánica personalizada con placas reforzadas, propulsores de velocidad o camuflaje sigiloso.', '{}'::text[], 'remaster', 'Armas & Engenhocas (Guns & Gears)', 16, '{"trainedSkills":["crafting"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_inventor_inovacao_de_arma', 'class.inventor', 'innovation', 'Inovação de Arma', 'Weapon Innovation', 'Innovación de Arma', 'Arma única modificada com engrenagens modulares, alcance estendido, segmentos afiados ou condutores de energia elemental.', 'Unique engineered weapon modified with modular damage mechanisms, extended reach, or elemental energy conductors.', 'Arma ingeniosa personalizada con mecanismos modulares, alcance extendido o conductores elementales.', '{}'::text[], 'remaster', 'Armas & Engenhocas (Guns & Gears)', 18, '{"trainedSkills":["crafting"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_inventor_inovacao_de_companheiro_constructo', 'class.inventor', 'innovation', 'Inovação de Companheiro Constructo', 'Construct Innovation', 'Innovación de Constructo', 'Autômato protótipo leal que luta ao seu lado e recebe melhorias mecânicas avançadas conforme você sobe de nível.', 'Loyal prototype mechanical construct fighting beside you and evolving with your custom inventions.', 'Autómata prototipo leal que lucha a tu lado y evoluciona con tus inventos mecánicos.', '{}'::text[], 'remaster', 'Armas & Engenhocas (Guns & Gears)', 20, '{"trainedSkills":["crafting"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_rogue_scoundrel', 'class.rogue', 'racket', 'Trapaceiro', 'Scoundrel', 'Granuja', 'Especialista em lábia, distrações e fintas desconcertantes. Você é treinado em Enganação e Diplomacia e ganha o talento Finta Ágil. Ao Fintar com sucesso, o alvo fica desprevenido contra seus ataques corpo a corpo até o final do seu próximo turno.', 'Master of silver-tongued bluffs and feints. Trained in Deception and Diplomacy and gains the Feint feat. When you successfully Feint, the target is off-guard against your melee attacks until the end of your next turn.', 'Maestro del engaño y las fintas desconcertantes. Entrenado en Engaño y Diplomacia y obtiene la dote Finta. Al fintar con éxito, el objetivo queda desprevenido ante tus ataques cuerpo a cuerpo hasta el final de tu próximo turno.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 168, '{"trainedSkills":["deception","diplomacy"],"grants":["feat.general.feint"],"needs_review":false}'::jsonb),
  ('subclass.class_rogue_thief', 'class.rogue', 'racket', 'Ladrão Furtivo', 'Thief', 'Ladrón', 'Mestre de mãos leves, arrombamentos e precisão letal. Você é treinado em Ladinagem. Adiciona seu modificador de Destreza em vez de Força às jogadas de dano com armas de acuidade (finesse) ou ataques desarmados de acuidade.', 'Master of quick hands, lockpicking, and lethal precision. Trained in Thievery. Adds your Dexterity modifier instead of Strength to damage rolls with finesse weapons or finesse unarmed attacks.', 'Maestro de manos rápidas y precisión letal. Entrenado en Latrocinio. Suma tu modificador de Destreza en vez de Fuerza al daño con armas sutiles (finesse) o ataques desarmados sutiles.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 169, '{"trainedSkills":["thievery"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_rogue_ruffian', 'class.rogue', 'racket', 'Bruto', 'Ruffian', 'Rufián', 'Ladino intimidador que usa força física bruta, clavas e armadura média. Você é treinado em Intimidação e armaduras médias. Pode aplicar Ataque Furtivo com qualquer arma simples corpo a corpo com dado de dano até d8.', 'Intimidating rogue who relies on brute force, clubs, and medium armor. Trained in Intimidation and medium armor. Can apply Sneak Attack with any simple melee weapon up to a d8 damage die.', 'Pícaro intimidador que confía en la fuerza física y armaduras intermedias. Entrenado en Intimidación y armaduras intermedias. Puede aplicar Ataque Furtivo con cualquier arma simple cuerpo a cuerpo de hasta d8.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 169, '{"trainedSkills":["intimidation"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_rogue_mastermind', 'class.rogue', 'racket', 'Mestre da Mente', 'Mastermind', 'Mente Maestra', 'Estrategista genial que decifra padrões táticos e pontos fracos dos oponentes. Você é treinado em Sociedade. Ao usar Lembrança Útil (Recall Knowledge) com sucesso contra uma criatura, ela fica desprevenida contra seus ataques até o final do seu próximo turno.', 'Genius tactician deducing enemy flaws and patterns. Trained in Society. When you successfully Recall Knowledge against a creature, that creature is off-guard against your attacks until the end of your next turn.', 'Estratega genial que deduce patrones y puntos débiles enemigos. Entrenado en Sociedad. Al usar Recordar Conocimiento con éxito contra una criatura, queda desprevenida ante tus ataques hasta el final de tu próximo turno.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 169, '{"trainedSkills":["society"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_rogue_eldritch_trickster', 'class.rogue', 'racket', 'Trapaceiro Sobrenatural', 'Eldritch Trickster', 'Pícaro Sobrenatural', 'Ladino versado nas artes místicas que mescla feitiçaria e furtividade. Você é treinado em uma perícia mágica e ganha uma dedicação de arquétipo multiclasse de conjurador no 1º nível.', 'Rogue blending spellcasting tricks with stealth. Trained in a magical skill and gains a spellcasting multiclass archetype dedication feat at 1st level.', 'Pícaro que combina artes mágicas con sigilo. Entrenado en una habilidad mágica y obtiene una dote de dedicación de clase de lanzador de conjuros a nivel 1.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 169, '{"trainedSkills":["arcana"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.school_ars_grammatica', 'class.wizard', 'arcaneSchool', 'Escola da Ars Grammatica', 'School of Ars Grammatica', 'Escuela de Ars Grammatica', 'Currículo arcano de Mago; concede a magia de escola inicial Guarita de Proteção.', 'Wizard arcane curriculum; grants the initial school spell Protective Wards.', 'Plan de estudios arcano de Mago; concede el conjuro inicial de escuela Guardas protectoras.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 186, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.school_protean_form', 'class.wizard', 'arcaneSchool', 'Escola da Forma Proteana', 'School of the Protean Form', 'Escuela de la Forma Proteica', 'Currículo arcano de Mago; concede a magia de escola inicial Embaralhar Corpo.', 'Wizard arcane curriculum; grants the initial school spell Scramble Body.', 'Plan de estudios arcano de Mago; concede el conjuro inicial de escuela Desordenar cuerpo.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 187, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.school_boundary', 'class.wizard', 'arcaneSchool', 'Escola dos Limiares', 'School of the Boundary', 'Escuela de los Límites', 'Currículo arcano de Mago; concede a magia de escola inicial Fortificar Convocação.', 'Wizard arcane curriculum; grants the initial school spell Fortify Summoning.', 'Plan de estudios arcano de Mago; concede el conjuro inicial de escuela Fortalecer invocación.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 187, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.school_battle_magic', 'class.wizard', 'arcaneSchool', 'Escola da Magia Bélica', 'School of Battle Magic', 'Escuela de Magia Bélica', 'Currículo arcano de Mago; concede a magia de escola inicial Raio de Força.', 'Wizard arcane curriculum; grants the initial school spell Force Bolt.', 'Plan de estudios arcano de Mago; concede el conjuro inicial de escuela Rayo de fuerza.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 188, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.school_civic_magic', 'class.wizard', 'arcaneSchool', 'Escola da Magia Cívica', 'School of Civic Magic', 'Escuela de Magia Cívica', 'Currículo arcano de Mago; concede a magia de escola inicial Terraplenagem.', 'Wizard arcane curriculum; grants the initial school spell Earthworks.', 'Plan de estudios arcano de Mago; concede el conjuro inicial de escuela Movimiento de tierras.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 188, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.school_mentalism', 'class.wizard', 'arcaneSchool', 'Escola do Mentalismo', 'School of Mentalism', 'Escuela del Mentalismo', 'Currículo arcano de Mago; concede a magia de escola inicial Ímpeto Cativante.', 'Wizard arcane curriculum; grants the initial school spell Charming Push.', 'Plan de estudios arcano de Mago; concede el conjuro inicial de escuela Impulso encantador.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 188, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.school_unified_magical_theory', 'class.wizard', 'arcaneSchool', 'Escola da Teoria Mágica Unificada', 'School of Unified Magical Theory', 'Escuela de Teoría Mágica Unificada', 'Currículo arcano de Mago; concede a magia de escola inicial Mão do Aprendiz.', 'Wizard arcane curriculum; grants the initial school spell Hand of the Apprentice.', 'Plan de estudios arcano de Mago; concede el conjuro inicial de escuela Mano del aprendiz.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 188, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.magus.hybrid_study_twisting_tree', 'class.magus', 'hybridStudy', 'Árvore Retorcida', 'Twisting Tree', 'Árbol retorcido', 'Transforma o cajado em arma marcial versátil e concede a magia de confluência Cajado Giratório.', 'Makes a staff a versatile martial weapon and grants the Spinning Staff conflux spell.', 'Convierte un bastón en un arma marcial versátil y concede el conjuro de confluencia Bastón giratorio.', '{}'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 62, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.magus.hybrid_study_inexorable_iron', 'class.magus', 'hybridStudy', 'Ferro Inexorável', 'Inexorable Iron', 'Hierro inexorable', 'Canaliza armas pesadas para resistir ao combate e concede Golpe Estrondoso como magia de confluência.', 'Channels heavy weapons to endure combat and grants Thunderous Strike as its conflux spell.', 'Canaliza armas pesadas para resistir el combate y concede Golpe atronador como conjuro de confluencia.', '{}'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 62, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.magus.hybrid_study_laughing_shadow', 'class.magus', 'hybridStudy', 'Sombra Jocosa', 'Laughing Shadow', 'Sombra jocosa', 'Aumenta mobilidade e dano contra alvos desprevenidos em Cascata Arcana; concede Agressão Dimensional.', 'Improves mobility and damage against off-guard targets in Arcane Cascade; grants Dimensional Assault.', 'Mejora movilidad y daño contra objetivos desprevenidos en Cascada arcana; concede Asalto dimensional.', '{}'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 62, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.magus.hybrid_study_sparkling_targe', 'class.magus', 'hybridStudy', 'Targe Cintilante', 'Sparkling Targe', 'Broquel centelleante', 'Aprimora o escudo contra efeitos mágicos em Cascata Arcana e concede Golpe e Escudo.', 'Improves a shield against magical effects in Arcane Cascade and grants Shielding Strike.', 'Mejora el escudo contra efectos mágicos en Cascada arcana y concede Golpe y escudo.', '{}'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 63, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.magus.hybrid_study_starlit_span', 'class.magus', 'hybridStudy', 'Vão Estrelado', 'Starlit Span', 'Vano estelar', 'Permite Golpe de Magia à distância no primeiro incremento e concede Estrela Cadente.', 'Allows ranged Spellstrike within the first range increment and grants Shooting Star.', 'Permite Golpe de conjuro a distancia dentro del primer incremento y concede Estrella fugaz.', '{}'::text[], 'legacy', 'Segredos da Magia (pré-Remaster)', 63, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_monk_postura_do_dragao', 'class.monk', 'style', 'Postura do Dragão', 'Dragon Stance', 'Postura del Dragón', 'Postura poderosa que concede Golpes de Cauda de Dragão (1d10 C, retrógrado) e permite ignorar terreno difícil em avanços rápidos.', 'Mighty stance granting Dragon Tail unarmed strikes (1d10 B, backswing) and ignoring difficult terrain on strides.', 'Postura poderosa que concede Golpes de Cola de Dragón (1d10 C, contragolpe) e ignora terreno difícil al avanzar.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 92, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_monk_postura_do_tigre', 'class.monk', 'style', 'Postura do Tigre', 'Tiger Stance', 'Postura del Tigre', 'Postura feroz que concede Golpes de Garra de Tigre (1d8 C/P, ágil, finesse) e dano por sangramento persistente em acertos críticos.', 'Ferocious stance granting Tiger Claw strikes (1d8 S/P, agile, finesse) and persistent bleed damage on critical hits.', 'Postura feroz que concede Golpes de Garra de Tigre (1d8 C/P, ágil, finesse) y sangrado persistente en críticos.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 93, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_monk_postura_do_grou', 'class.monk', 'style', 'Postura do Grou', 'Crane Stance', 'Postura de la Grulla', 'Postura defensiva e acrobática que concede +1 de bônus de circunstância na CA e Golpes de Asa de Grou (1d6 C, ágil, finesse).', 'Acrobatic defensive stance granting a +1 circumstance bonus to AC and Crane Wing strikes (1d6 B, agile, finesse).', 'Postura acrobática que concede +1 circunstancial a la CA y Golpes de Ala de Grulla (1d6 C, ágil, finesse).', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 93, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_monk_postura_da_montanha', 'class.monk', 'style', 'Postura da Montanha', 'Mountain Stance', 'Postura de la Montaña', 'Postura enraizada que concede +4 de bônus de estado na CA (limite Des +0), Golpes de Rocha que Cai (1d8 C) e resistência contra derrubadas.', 'Rooted stance granting +4 item bonus to AC (Dex cap +0), Falling Stone strikes (1d8 B), and bonuses against trip/shove.', 'Postura enraizada que concede +4 a la CA (límite Des +0), Golpes de Roca que Cae (1d8 C) y resistencia al derribo.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 94, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_monk_postura_do_lobo', 'class.monk', 'style', 'Postura do Lobo', 'Wolf Stance', 'Postura del Lobo', 'Postura predatória que concede Golpes de Mandíbula de Lobo (1d8 P, finesse, ágil contra flanqueados) e sinergia letal de derrubada.', 'Predatory stance granting Wolf Jaw strikes (1d8 P, finesse, agile vs flat-footed) and trip synergy.', 'Postura depredadora que concede Golpes de Mandíbula de Lobo (1d8 P, finesse) y sinergia para derribar.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 94, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_monk_postura_dos_ventos', 'class.monk', 'style', 'Postura dos Ventos', 'Monastic Wind Stance', 'Postura de los Vientos', 'Postura veloz com disparos de projéteis de vento e rajadas acrobáticas fluidas.', 'Swift gale stance unleashing ranged wind blasts and fluid dashes.', 'Postura veloz que desata ráfagas de viento y desplazamientos fluidos.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 95, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.oracle.mystery_ancestors', 'class.oracle', 'mystery', 'Mistério dos Ancestrais', 'Ancestors', 'Antepasados', 'Vozes das gerações passadas guiam e atrapalham suas ações.', 'Voices of past generations guide and hinder your actions.', 'Las voces de generaciones pasadas guían y dificultan tus acciones.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 161, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.oracle.mystery_battle', 'class.oracle', 'mystery', 'Mistério da Batalha', 'Battle', 'Batalla', 'Forças bélicas concedem poder físico e conhecimento tático.', 'Warlike forces grant physical power and tactical knowledge.', 'Fuerzas bélicas conceden poder físico y conocimiento táctico.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 161, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.oracle.mystery_bones', 'class.oracle', 'mystery', 'Mistério dos Ossos', 'Bones', 'Huesos', 'A morte está próxima e os mortos conversam com você.', 'Death is close, and the dead speak with you.', 'La muerte está cerca y los muertos hablan contigo.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 162, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.oracle.mystery_flames', 'class.oracle', 'mystery', 'Mistério das Chamas', 'Flames', 'Llamas', 'O fogo alimenta seu poder e exige que você permaneça em movimento.', 'Fire fuels your power and demands that you keep moving.', 'El fuego alimenta tu poder y exige que sigas moviéndote.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 161, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.oracle.mystery_cosmos', 'class.oracle', 'mystery', 'Mistério dos Cosmos', 'Cosmos', 'Cosmos', 'As estrelas e o espaço entre elas concedem seu poder.', 'The stars and the space between them grant your power.', 'Las estrellas y el espacio entre ellas conceden tu poder.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 162, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.oracle.mystery_lore', 'class.oracle', 'mystery', 'Mistério do Saber', 'Lore', 'Saber', 'Conhecimento vasto e avassalador transborda para sua mente.', 'Vast and overwhelming knowledge pours into your mind.', 'Un conocimiento vasto y abrumador inunda tu mente.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 163, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.oracle.mystery_tempest', 'class.oracle', 'mystery', 'Mistério das Tempestades', 'Tempest', 'Tempestad', 'Ventos, ondas e tempestades respondem ao seu chamado.', 'Winds, waves, and storms answer your call.', 'Vientos, olas y tormentas responden a tu llamado.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 163, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.oracle.mystery_life', 'class.oracle', 'mystery', 'Mistério da Vida', 'Life', 'Vida', 'As energias vibrantes da vida fluem através de você e pelo mundo.', 'The vibrant energies of life flow through you and the world.', 'Las energías vibrantes de la vida fluyen por ti y por el mundo.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 163, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_ranger_precision', 'class.ranger', 'hunterEdge', 'Vantagem: Precisão', 'Precision', 'Precisión', 'O primeiro Golpe bem-sucedido a cada rodada contra a presa caçada causa 1d8 de dano de precisão adicional (aumenta para 2d8 no 11º nível e 3d8 no 19º nível).', 'Your first successful Strike each round against your hunted prey deals an additional 1d8 precision damage (2d8 at 11th level, 3d8 at 19th level).', 'Tu primer Golpe con éxito en cada asalto contra la presa inflige 1d8 de daño de precisión adicional (2d8 a nivel 11, 3d8 a nivel 19).', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 154, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb)
insert into public.catalog_subclasses (id, class_id, choice_field, name_pt, name_en, name_es, description_pt, description_en, description_es, traits, ruleset, source_book, source_page, data)
values
  ('subclass.class_ranger_flurry', 'class.ranger', 'hunterEdge', 'Vantagem: Rajada', 'Flurry', 'Ráfaga', 'Reduz a penalidade por ataques múltiplos contra a presa caçada para -3 no segundo ataque e -6 no terceiro (ou -2 / -4 com armas que possuem o traço ágil).', 'Reduces multiple attack penalties against hunted prey to -3 on the second attack and -6 on subsequent attacks (-2 / -4 with agile weapons).', 'Reduce la penalización por ataques múltiples contra la presa a -3 en el segundo ataque y -6 en los siguientes (-2 / -4 con armas ágiles).', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 154, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_ranger_outwit', 'class.ranger', 'hunterEdge', 'Vantagem: Desencorajar', 'Outwit', 'Burlar', 'Concede +2 de bônus de circunstância na CA contra ataques da presa, +2 em testes de Enganação, Intimidação e Furtividade contra ela, e +2 em Lembrança Útil sobre ela.', 'Grants a +2 circumstance bonus to AC against prey''s attacks, +2 to Deception, Intimidation, and Stealth against prey, and +2 to Recall Knowledge.', 'Concede un bonificador circunstancial de +2 a la CA contra ataques de la presa, y +2 a Engaño, Intimidación, Sigilo y Recordar Conocimiento.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 155, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_gunslinger_pistolero', 'class.gunslinger', 'way', 'Caminho do Pistoleiro', 'Way of the Pistolero', 'Camino del Pistolero', 'Mestre em duelos rápidos com arma de fogo em uma mão, lábia e presença de palco. Treinado em Enganação ou Intimidação. Concede a ação Recarga Rápida (Raconteur''s Reload) e a habilidade Dez Passos (+2 na iniciativa e saca arma como reação livre).', 'Quick-draw duelist specializing in one-handed firearms and bravado. Trained in Deception or Intimidation. Grants Raconteur''s Reload and Ten Paces (+2 initiative, free weapon draw).', 'Duelista veloz con armas de fuego a una mano y presencia escénica. Entrenado en Engaño o Intimidación. Concede Recarga Rápida y Diez Pasos (+2 iniciativa, desenfunde libre).', '{}'::text[], 'remaster', 'Armas & Engenhocas (Guns & Gears)', 108, '{"trainedSkills":["deception"],"grants":["action.raconteurs_reload","feat.general.ten_paces"],"needs_review":false}'::jsonb),
  ('subclass.class_gunslinger_sniper', 'class.gunslinger', 'way', 'Caminho do Franco-Atirador', 'Way of the Sniper', 'Camino del Francotirador', 'Atirador de precisão letal oculto à distância. Treinado em Furtividade. Concede a ação Recarga Oculta (Covered Reload) e Um Tiro, Um Abate (+1d6 de dano de precisão no primeiro disparo).', 'Lethal sharpshooter striking from long range and concealment. Trained in Stealth. Grants Covered Reload and One Shot, One Kill (+1d6 precision damage on first Strike).', 'Tirador de precisión letal oculto a larga distancia. Entrenado en Sigilo. Concede Recarga a Cubierto y Un Tiro, Una Baja (+1d6 de daño de precisión en el primer disparo).', '{}'::text[], 'remaster', 'Armas & Engenhocas (Guns & Gears)', 109, '{"trainedSkills":["stealth"],"grants":["action.covered_reload","feat.general.one_shot_one_kill"],"needs_review":false}'::jsonb),
  ('subclass.class_gunslinger_vanguard', 'class.gunslinger', 'way', 'Caminho da Vanguarda', 'Way of the Vanguard', 'Camino de la Vanguardia', 'Lutador de infantaria pesada armado com bacamartes e armas de dispersão. Treinado em Atletismo. Concede a ação Limpar Caminho (Clear a Path) e Armadura Viva (+1 na CA ao sacar arma).', 'Heavy frontline combatant with scatterguns and wide blasts. Trained in Athletics. Grants Clear a Path (Shove with firearm) and Living Fortification (+1 AC upon weapon draw).', 'Combatiente de primera línea armado con trabucos y dispersión. Entrenado en Atletismo. Concede Despejar el Camino y Fortificación Viviente (+1 a la CA al desenfundar).', '{}'::text[], 'remaster', 'Armas & Engenhocas (Guns & Gears)', 110, '{"trainedSkills":["athletics"],"grants":["action.clear_a_path","feat.general.living_fortification"],"needs_review":false}'::jsonb),
  ('subclass.class_gunslinger_drifter', 'class.gunslinger', 'way', 'Caminho do Andarilho', 'Way of the Drifter', 'Camino del Vagabundo', 'Guerreiro fluído que empunha uma arma de fogo em uma mão e uma espada na outra. Treinado em Acrobacia. Concede a ação Golpe de Recarga (Reloading Strike) para golpear corpo a corpo e recarregar na mesma ação.', 'Fluid skirmisher wielding a firearm in one hand and a blade in the other. Trained in Acrobatics. Grants Reloading Strike to strike in melee and reload in the same action.', 'Guerrero fluido con arma de fuego a una mano y espada en la otra. Entrenado en Acrobacias. Concede Golpe de Recarga para golpear cuerpo a cuerpo y recargar a la vez.', '{}'::text[], 'remaster', 'Armas & Engenhocas (Guns & Gears)', 111, '{"trainedSkills":["acrobatics"],"grants":["action.reloading_strike"],"needs_review":false}'::jsonb),
  ('subclass.class_psychic_telecinese', 'class.psychic', 'consciousMind', 'Mente Distante (Telecinese)', 'The Distant Grasp', 'La Mente Distante', 'Manipulação de forças cinéticas à distância. Treinado em Atletismo. Concede Projétil Telecinético e Mão Mágica amplificados.', 'Kinetic manipulation from afar. Trained in Athletics. Grants amplified Telekinetic Projectile and Mage Hand.', 'Manipulación cinética a distancia. Entrenado en Atletismo. Concede Proyectil Telecinético y Mano de Mago amplificados.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 16, '{"trainedSkills":["athletics"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_psychic_mente_infinita', 'class.psychic', 'consciousMind', 'Mente Infinita', 'The Infinite Eye', 'El Ojo Infinito', 'Percepção onisciente e clarividência mental. Treinado em Sociedade. Concede Orientação (Guidance) e Detectar Magia amplificados.', 'Omniscient perception and psychic foresight. Trained in Society. Grants amplified Guidance and Detect Magic.', 'Percepción omnisciente y clarividencia. Entrenado en Sociedad. Concede Guía y Detectar Magia amplificados.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 17, '{"trainedSkills":["society"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_psychic_mente_calosa', 'class.psychic', 'consciousMind', 'Mente Calosa / Onda Oscilante', 'The Oscillating Wave', 'La Onda Oscilante', 'Transferência termodinâmica de frio e calor extremos. Treinado em Natureza. Concede Produzir Chama e Raio de Gelo amplificados.', 'Thermodynamic extremes of searing heat and freezing cold. Trained in Nature. Grants amplified Produce Flame and Ray of Frost.', 'Transferencia termodinámica de frío y calor extremos. Entrenado en Naturaleza. Concede Producir Llama y Rayo de Escarcha amplificados.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 18, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_psychic_mente_tangivel', 'class.psychic', 'consciousMind', 'Mente Tangível', 'The Tangible Dream', 'El Sueño Tangible', 'Projeção de matéria astral sólida e geometrias tangíveis. Treinado em Manufatura. Concede Escudo e Luzes Dançantes amplificados.', 'Solid astral constructs and tangible force shields. Trained in Crafting. Grants amplified Shield and Dancing Lights.', 'Construcciones de materia astral sólida. Entrenado en Artesanía. Concede Escudo y Luces Danzantes amplificados.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 20, '{"trainedSkills":["crafting"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_thaumaturge_implemento_amuleto', 'class.thaumaturge', 'implement', 'Implemento: Amuleto', 'Amulet Implement', 'Implemento de Amuleto', 'Símbolo protetor consagrado. Concede a reação Interposição do Amuleto para conceder resistência a dano a você ou a um aliado próximo.', 'Consecrated protective ward. Grants the Amulet''s Abeyance reaction to grant damage resistance to you or a nearby ally.', 'Símbolo protector consagrado. Concede la reacción Amparo del Amuleto para otorgar resistencia a daño a ti o a un aliado.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 40, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_thaumaturge_implemento_calice', 'class.thaumaturge', 'implement', 'Implemento: Cálice', 'Chalice Implement', 'Implemento de Cáliz', 'Recipiente de comunhão mística. Concede a ação Beber do Cálice para restaurar pontos de vida temporários ou curar ferimentos em combate.', 'Mystic communion vessel. Grants Drink from the Chalice to gain temporary HP or heal wounds in combat.', 'Recipiente místico. Concede Beber del Cáliz para ganar PG temporales o sanar heridas en combate.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 40, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_thaumaturge_implemento_lanterna', 'class.thaumaturge', 'implement', 'Implemento: Lanterna', 'Lantern Implement', 'Implemento de Linterna', 'Farol que revela verdades ocultas. Emite uma aura brilhante que revela criaturas invisíveis, ilusões e perigos ocultos a até 6m.', 'Beacon of hidden truths. Emits a bright aura revealing invisible foes, illusions, and hidden hazards within 20 ft.', 'Faro de verdades ocultas. Emite un aura que revela criaturas invisibles, ilusiones y secretos ocultos a 6m.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 41, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_thaumaturge_implemento_espelho', 'class.thaumaturge', 'implement', 'Implemento: Espelho', 'Mirror Implement', 'Implemento de Espejo', 'Superfície reflexiva extradimensional. Concede a ação Reflexo do Espelho para projetar um duplo ilusório e se teletransportar entre posições.', 'Extradimensional reflective glass. Grants Mirror''s Reflection to project an illusory double and teleport across space.', 'Superficie reflectante extradimensional. Concede Reflejo del Espejo para proyectar un doble ilusorio y teletransportarse.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 41, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_thaumaturge_implemento_arma', 'class.thaumaturge', 'implement', 'Implemento: Arma', 'Weapon Implement', 'Implemento de Arma', 'Instrumento marcial imbuído de retaliação sobrenatural. Concede a reação Interrupção do Implemento para realizar Golpes Reativos punitivos.', 'Martial conduit infused with supernatural retribution. Grants Implement''s Interruption reaction to strike provoking foes.', 'Instrumento marcial imbuido de represalia. Concede la reacción Interrupción del Implemento para contraatacar enemigos.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 42, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_thaumaturge_implemento_livro', 'class.thaumaturge', 'implement', 'Implemento: Livro', 'Tome Implement', 'Implemento de Libro', 'Grimório de conhecimento infinito. Concede proficiência temporária treinada em duas perícias à sua escolha a cada preparação diária.', 'Grimoire of endless occult lore. Grants temporary trained proficiency in two chosen skills each daily preparation.', 'Grimorio de conocimiento infinito. Concede competencia entrenada temporal en dos habilidades a tu elección cada día.', '{}'::text[], 'remaster', 'Arquivo Sombrio (Dark Archive)', 42, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_exemplar_legacy_alias_exemplar_exemplar_gleaming_blade', 'class.exemplar.legacy_alias.exemplar_exemplar', NULL, 'Centelha da Lâmina Radiante', 'Gleaming Blade', 'Hoja Radiante', 'Centelha divina de pura glória marcial que faz sua arma emitir luz sagrada e desferir golpes fulminantes.', 'Divine spark of martial glory causing your weapon to flare with holy radiance and cleaving strikes.', 'Chispa divina de gloria marcial que hace brillar tu arma con fulgor sagrado.', '{}'::text[], 'remaster', 'Guerra dos Imortais (War of Immortals)', 18, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_exemplar_legacy_alias_exemplar_exemplar_mountain_s_scar', 'class.exemplar.legacy_alias.exemplar_exemplar', NULL, 'Centelha da Cicatriz da Montanha', 'Mountain''s Scar', 'Cicatriz de la Montaña', 'Centelha divina de resistência telúrica inabalável que endurece sua pele como granito contra dano.', 'Divine spark of unyielding telluric resilience hardening your skin into impenetrable granite.', 'Chispa divina de resistencia telúrica que endurece tu piel como granito.', '{}'::text[], 'remaster', 'Guerra dos Imortais (War of Immortals)', 19, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_exemplar_legacy_alias_exemplar_exemplar_radiant_halo', 'class.exemplar.legacy_alias.exemplar_exemplar', NULL, 'Centelha da Coroa Solar', 'Radiant Halo', 'Halo Radiante', 'Centelha divina de majestade solar que emite um halo de autoridade e energia curativa protetora.', 'Divine spark of solar majesty emitting a glowing crown of authority and protective healing.', 'Chispa divina de majestad solar que emite una corona radiante de autoridad y sanación.', '{}'::text[], 'remaster', 'Guerra dos Imortais (War of Immortals)', 20, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_exemplar_legacy_alias_exemplar_exemplar_celestial_beast', 'class.exemplar.legacy_alias.exemplar_exemplar', NULL, 'Centelha da Fera Celestial', 'Celestial Beast', 'Bestia Celestial', 'Centelha divina de ferocidade cósmica que aprimora seus instintos predatórios e velocidade de caça.', 'Divine spark of cosmic ferocity enhancing your predatory instincts and boundless hunting speed.', 'Chispa divina de ferocidad cósmica que potencia tus instintos depredadores y velocidad de caza.', '{}'::text[], 'remaster', 'Guerra dos Imortais (War of Immortals)', 21, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_animist_liturgista', 'class.animist', 'apparition', 'Liturgista', 'Liturgist', 'Liturgista', 'Animista litúrgico que organiza rituais sagrados e canaliza espíritos divinos com orações estruturadas e bônus de sustentação.', 'Liturgical animist structuring sacred rites and channeling divine apparitions through communal ceremonies.', 'Animista litúrgico que organiza ritos sagrados y canaliza apariciones divinas a través de ceremonias.', '{}'::text[], 'remaster', 'Guerra dos Imortais (War of Immortals)', 34, '{"trainedSkills":["religion"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_animist_medium', 'class.animist', 'apparition', 'Médium', 'Medium', 'Médium', 'Canalizador psíquico que permite a espíritos inquietos habitarem temporariamente seu corpo para desferir ataques espirituais.', 'Psychic conduit allowing restless spirits to temporarily possess their body to unleash spiritual attacks.', 'Conducto psíquico que permite a espíritus inquietos habitar temporalmente su cuerpo para ataques espirituales.', '{}'::text[], 'remaster', 'Guerra dos Imortais (War of Immortals)', 35, '{"trainedSkills":["occultism"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_animist_xama', 'class.animist', 'apparition', 'Xamã', 'Shaman', 'Chamán', 'Guardião espiritual primal que se comunica com espíritos de rios, montanhas e florestas antigas.', 'Primal spirit guardian communicating directly with ancient forest and mountain spirits.', 'Guardián espiritual primigenio que se comunica con espíritus de la naturaleza y bosques antiguos.', '{}'::text[], 'remaster', 'Guerra dos Imortais (War of Immortals)', 36, '{"trainedSkills":["nature"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class_exemplar_icones_e_epitetos', 'class.exemplar', 'icon', 'Ícones e Epítetos Divinos', 'Icons and Epithets', 'Iconos y Epítetos', 'Manifestações da centelha divina que personificam feitos lendários e poderes de divindades em ascensão.', 'Manifestations of the divine spark embodying legendary deeds and rising deific powers.', 'Manifestaciones de la chispa divina que personifican hazañas legendarias y poderes en ascenso.', '{}'::text[], 'remaster', 'Guerra dos Imortais (War of Immortals)', 16, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.thesis_spell_blending', 'class.wizard', 'wizardThesis', 'Mescla de Magia', 'Spell Blending', 'Mezcla de conjuros', 'Troca dois espaços de mesmo ranque por um espaço até dois ranques maior durante as preparações.', 'Trades two same-rank slots for one slot up to two ranks higher during daily preparations.', 'Cambia dos espacios del mismo rango por uno de hasta dos rangos mayor durante las preparaciones.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 183, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.thesis_experimental_spellshape', 'class.wizard', 'wizardThesis', 'Moldamagia Experimental', 'Experimental Spellshape', 'Moldeado de conjuros experimental', 'Concede um talento de moldamagia de Mago de 1º nível e permite trocar a escolha nas preparações a partir do 4º nível.', 'Grants a 1st-level Wizard spellshape feat and allows changing it during preparations from 4th level.', 'Otorga una dote de moldeado de conjuros de Mago de nivel 1 y permite cambiarla durante las preparaciones desde nivel 4.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 183, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.thesis_staff_nexus', 'class.wizard', 'wizardThesis', 'Nexo de Cajado', 'Staff Nexus', 'Nexo de bastón', 'Concede um cajado improvisado e permite carregar o cajado durante as preparações diárias.', 'Grants an improvised staff and lets you charge the staff during daily preparations.', 'Otorga un bastón improvisado y permite cargarlo durante las preparaciones diarias.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 183, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.thesis_improved_familiar_attunement', 'class.wizard', 'wizardThesis', 'Sintonização com Familiar Aprimorada', 'Improved Familiar Attunement', 'Sintonización mejorada con familiar', 'Concede Familiar, uma habilidade adicional e Drenar Familiar em vez de Drenar Item Vinculado.', 'Grants Familiar, one extra familiar ability, and Drain Familiar instead of Drain Bonded Item.', 'Otorga Familiar, una habilidad adicional y Drenar Familiar en vez de Drenar objeto vinculado.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 183, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.wizard.thesis_spell_substitution', 'class.wizard', 'wizardThesis', 'Substituição de Magia', 'Spell Substitution', 'Sustitución de conjuros', 'Permite gastar 10 minutos para trocar uma magia preparada por outra do grimório em um espaço vazio.', 'Lets you spend 10 minutes to replace a prepared spell with another spell from your spellbook in an empty slot.', 'Permite gastar 10 minutos para sustituir un conjuro preparado por otro del libro de conjuros en un espacio vacío.', '{}'::text[], 'remaster', 'Livro do Jogador (Player Core, Remaster)', 183, '{"trainedSkills":[],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.champion.cause_esplendor', 'class.champion', NULL, 'Causa do Esplendor', 'Cause of Splendor', 'Causa del Esplendor', 'Você personifica a luz solar magnífica, a beleza inspiradora e a glória divina em batalha, cegando aqueles que ousam desafiar sua virtude. Treinado em Diplomacia.', 'You embody magnificent solar light, inspiring beauty, and divine glory in battle, dazzling those who dare challenge your virtue. Trained in Diplomacy.', 'Personificas la luz solar magnífica, la belleza inspiradora y la gloria divina en combate, cegando a quienes desafían tu virtud. Entrenado en Diplomacia.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 90, '{"trainedSkills":["diplomacy"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.champion.cause_iniquidade', 'class.champion', NULL, 'Causa da Iniquidade', 'Cause of Iniquity', 'Causa de la Iniquidad', 'Você explora impiedosamente fraquezas morais, enganações e vícios mortais para quebrar a honra de seus adversários. Treinado em Enganação.', 'You ruthlessly exploit moral vulnerabilities, deceit, and vices to erode your foes'' integrity and resolve. Trained in Deception.', 'Explotas despiadadamente debilidades morales, engaños y vicios mortales para quebrar la integridad enemiga. Entrenado en Engaño.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 90, '{"trainedSkills":["deception"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.champion.cause_libertacao', 'class.champion', NULL, 'Causa da Libertação', 'Cause of Liberation', 'Causa de la Liberación', 'Você quebra correntes de tirania e defende a autonomia absoluta. Concede a reação Passo Libertador (Liberating Step) para reduzir o dano sofrido por aliados e permitir fuga imediata de agarrões ou restrições.', 'You shatter chains of tyranny and champion absolute freedom. Grants the Liberating Step reaction to reduce ally damage and allow immediate escape from grabs and restraints.', 'Rompes cadenas de tiranía y defiendes la libertad absoluta. Concede la reacción Paso Liberador para reducir el daño a aliados y permitir escape inmediato de agarres.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 91, '{"trainedSkills":["religion"],"grants":["action.liberating_step"],"needs_review":false}'::jsonb),
  ('subclass.class.champion.cause_justica', 'class.champion', NULL, 'Causa da Justiça', 'Cause of Justice', 'Causa de la Justicia', 'Você defende a lei suprema e pune aqueles que ferem os inocentes. Concede a reação Golpe Retributivo (Retributive Strike) para proteger um aliado próximo e desferir um contra-ataque imediato contra o agressor.', 'You uphold righteous law and punish those who harm the innocent. Grants the Retributive Strike reaction to shield a nearby ally and immediately strike back at the attacker.', 'Defiendes la ley sagrada y castigas a quienes dañan a los inocentes. Concede la reacción Golpe Retributivo para proteger a un aliado y contraatacar de inmediato.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 91, '{"trainedSkills":["religion"],"grants":["action.retributive_strike"],"needs_review":false}'::jsonb),
  ('subclass.class.champion.cause_obediencia', 'class.champion', NULL, 'Causa da Obediência', 'Cause of Obedience', 'Causa de la Obediencia', 'Você impõe ordem rígida, hierarquia divina e disciplina militar implacável sobre seus inimigos. Treinado em Intimidação.', 'You enforce rigid hierarchy, divine law, and relentless military discipline upon your foes. Trained in Intimidation.', 'Impones jerarquía estricta, ley divina y disciplina implacable sobre tus enemigos. Entrenado en Intimidación.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 92, '{"trainedSkills":["intimidation"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.champion.cause_profanacao', 'class.champion', NULL, 'Causa da Profanação', 'Cause of Desecration', 'Causa de la Profanación', 'Você espalha blasfêmia, conspurcação e ruína abissal, infligindo dor atroz sobre quem ousa atacá-lo. Treinado em Religião.', 'You spread defilement, blasphemy, and ruin, inflicting agonizing damage upon any foolish enough to strike you. Trained in Religion.', 'Siembras blasfemia, profanación y ruina, infligiendo dolor atroz a cualquiera que ose atacarte. Entrenado en Religión.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 92, '{"trainedSkills":["religion"],"grants":null,"needs_review":false}'::jsonb),
  ('subclass.class.champion.cause_redencao', 'class.champion', NULL, 'Causa da Redenção', 'Cause of Redemption', 'Causa de la Redención', 'Você oferece misericórdia e restauração pacificadora aos corações violentos. Concede a reação Vislumbre da Redenção (Glimpse of Redemption) para forçar agressores a escolher entre não causar dano ou sofrer penalidades paralisantes.', 'You offer mercy, forgiveness, and pacifying restoration to violent souls. Grants the Glimpse of Redemption reaction forcing foes to choose between sparing their target or suffering debilitating penalties.', 'Ofreces piedad y redención pacificadora a las almas violentas. Concede la reacción Atisbo de Redención para forzar a los agresores a no causar daño o sufrir penalizaciones.', '{}'::text[], 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 93, '{"trainedSkills":["religion"],"grants":["action.glimpse_of_redemption"],"needs_review":false}'::jsonb)
insert into public.catalog_backgrounds (id, name_pt, name_en, name_es, description_pt, description_en, description_es, attribute_boosts, trained_skills, granted_feat, lore_skill, rarity, ruleset, source_book, source_page, data)
values
  ('background.acrobat', 'Acróbata', 'Acrobat', 'Acróbata', 'Você treinou acrobacias, equilíbrio e saltos espetaculares para encantar multidões ou superar obstáculos perigosos.', 'You practiced acrobatics, balance, and spectacular jumps to delight crowds or overcome dangerous obstacles.', 'Entrenaste acrobacias, equilibrio y saltos espectaculares para deleitar a las multitudes o superar obstáculos peligrosos.', '{}'::text[], '"acrobatics"'::text[], 'Acrobata Felino', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 88, '{"needs_review":false}'::jsonb),
  ('background.artisan', 'Artesão', 'Artisan', 'Artesano', 'Como aprendiz de uma oficina ou guilda, você aprendeu a forjar, talhar ou tecer artigos úteis e obras de qualidade com ferramentas manuais.', 'As an apprentice in a workshop or guild, you learned to forge, carve, or weave useful goods and quality craftwork with hand tools.', 'Como aprendiz en un taller o gremio, aprendiste a forjar, tallar o tejer bienes útiles y obras de calidad con herramientas manuales.', '{}'::text[], '"crafting"'::text[], 'Manufatura Especializada', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 88, '{"needs_review":false}'::jsonb),
  ('background.artist', 'Artista', 'Artist', 'Artista', 'Você expressa sua visão criativa por meio de pintura, escultura, poesia ou música, criando obras que movem corações e mentes.', 'You express your creative vision through painting, sculpture, poetry, or music, making works that move hearts and minds.', 'Expresas tu visión creativa a través de la pintura, escultura, poesía o música, creando obras que conmueven corazones y mentes.', '{}'::text[], '"crafting"'::text[], 'Manufatura Especializada', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 88, '{"needs_review":false}'::jsonb),
  ('background.wilderness_scout', 'Batedor Selvagem', 'Wilderness Scout', 'Explorador de avanzada', 'Você guiou caravanas e exércitos por terras inexploradas, reconhecendo perigos naturais e emboscadas antes de todos.', 'You guided caravans and armies through uncharted lands, spotting natural hazards and ambushes before anyone else.', 'Guiaste caravanas y ejércitos por tierras inexploradas, detectando peligros naturales y emboscadas antes que nadie.', '{}'::text[], '"survival"'::text[], 'Rastreio Experiente', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 90, '{"needs_review":false}'::jsonb),
  ('background.hunter', 'Caçador', 'Hunter', 'Cazador', 'Você perseguiu presas em florestas e montanhas, aprendendo o comportamento da fauna e as técnicas de emboscada e abate.', 'You tracked prey through forests and mountains, learning animal behavior and ambush and harvesting techniques.', 'Rastreaste presas por bosques y montañas, aprendiendo el comportamiento animal y las técnicas de emboscada y aprovechamiento.', '{}'::text[], '"survival"'::text[], 'Olhos de Águia', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.charlatan', 'Charlatão', 'Charlatan', 'Charlatán', 'Você viajou vendendo elixires falsos, falsas promessas e esquemas astutos, escapando sempre antes que a farsa fosse descoberta.', 'You learned to charm, tell convincing falsehoods, and sell dubious wonders while staying one step ahead of the law.', 'Viajaste vendiendo elixires falsos, promesas vanas y astutas estafas, escapando siempre antes de que se descubriera la farsa.', '{}'::text[], '"deception"'::text[], 'Mentiroso Charmoso', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 88, '{"needs_review":false}'::jsonb),
  ('background.cook', 'Cozinheiro', 'Cook', 'Cocinero', 'Em tavernas barulhentas, navios ou acampamentos de campanha, você alimentou bocas famintas e aprendeu a identificar ingredientes raros e especiarias.', 'In bustling taverns, ships, or military camps, you fed hungry mouths and learned to identify rare ingredients and spices.', 'En tabernas concurridas, barcos o campamentos militares, alimentaste a bocas hambrientas y aprendiste a identificar ingredientes y especias raros.', '{}'::text[], '"survival"'::text[], 'Forrageador', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 88, '{"needs_review":false}'::jsonb),
  ('background.criminal', 'Criminoso', 'Criminal', 'Criminal', 'Você sobreviveu nos becos escuros praticando arrombamento, furto ou contrabando, sempre atento à ronda da guarda urbana.', 'You survived in dark alleys practicing burglary, theft, or smuggling, always wary of the city guard patrols.', 'Sobreviviste en callejones oscuros practicando robos, hurtos o contrabando, siempre atento a las patrullas de la guardia urbana.', '{}'::text[], '"thievery"'::text[], 'Pernas Rápidas', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 88, '{"needs_review":false}'::jsonb),
  ('background.field_medic', 'Curandeiro de Campo', 'Field Medic', 'Médico de campo', 'Em meio ao caos do combate, você estancou sangramentos, estabilizou soldados caídos e tratou ferimentos graves sob fogo cerrado.', 'Amid the chaos of battle, you stopped bleeding, stabilized fallen soldiers, and treated severe wounds under heavy fire.', 'En medio del caos del combate, detuviste hemorragias, estabilizaste soldados caídos y trataste heridas graves bajo fuego intenso.', '{}'::text[], '"medicine"'::text[], 'Medicina de Batalha', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.detective', 'Detetive', 'Detective', 'Detective', 'Você investigou mistérios urbanos, interrogou suspeitos e desvendou tramas criminosas conectando pequenas pistas esquecidas.', 'You investigated urban mysteries, interrogated suspects, and uncovered criminal plots by linking subtle forgotten clues.', 'Investigaste misterios urbanos, interrogaste sospechosos y desentrañaste tramas criminales uniendo pequeñas pistas olvidadas.', '{}'::text[], '"society"'::text[], 'Leitura de Pista', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.dueling_noble', 'Duelista de Oppara', 'Dueling Noble', 'Noble duelista', 'Treinado nos salões e academias de duelo de Taldor, você combina esgrima refinada e insultos afiados para desestabilizar rivais.', 'Trained in the dueling salons and academies of Taldor, you combine refined swordplay with sharp wit to unbalance rivals.', 'Entrenado en los salones y academias de duelo de Taldor, combinas esgrima refinada y agudos insultos para desestabilizar rivales.', '{}'::text[], '"deception"'::text[], 'Palavra Mordaz (Bon Mot)', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.emissary', 'Emissário', 'Emissary', 'Emisario', 'Você atuou como porta-voz, diplomata ou mensageiro entre governantes e facções, negociando tratados e acordos delicados.', 'You served as a spokesperson, diplomat, or messenger between rulers and factions, brokering delicate treaties and pacts.', 'Actuaste como portavoz, diplomático o mensajero entre gobernantes y facciones, negociando tratados y acuerdos delicados.', '{}'::text[], '"diplomacy"'::text[], 'Etiqueta da Corte', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.hermit', 'Eremita', 'Hermit', 'Eremita', 'Isolado em cavernas, picos ou ermos distantes, você dedicou anos à contemplação e à comunhão com segredos esquecidos do mundo.', 'Isolated in caves, peaks, or remote wilderness, you spent years in contemplation and communion with forgotten secrets of the world.', 'Aislado en cuevas, cumbres o páramos remotos, dedicaste años a la contemplación y a la comunión con secretos olvidados del mundo.', '{}'::text[], '"nature"'::text[], 'Solidão Focada', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.squire', 'Escudeiro', 'Squire', 'Escudero', 'A serviço de um cavaleiro ou campeão, você cuidou de armas, armaduras pesadas e montarias, aprendendo o código marcial e a disciplina das armas.', 'Serving a knight or champion, you tended to weapons, heavy armor, and steeds, learning the martial code and weapons discipline.', 'Al servicio de un caballero o campeón, cuidaste armas, armaduras pesadas y monturas, aprendiendo el código marcial y la disciplina bélica.', '{}'::text[], '"athletics"'::text[], 'Mover Armadura', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 91, '{"needs_review":false}'::jsonb),
  ('background.scholar', 'Estudante da Academia', 'Scholar', 'Erudito', 'Você passou noites imerso em arquivos e bibliotecas, dominando teorias arcanas, históricas ou naturais com rigor acadêmico.', 'You spent countless nights in archives and libraries, mastering arcane, historical, or natural theories with academic rigor.', 'Pasaste noches inmerso en archivos y bibliotecas, dominando teorías arcanas, históricas o naturales con rigor académico.', '{}'::text[], '"arcana"'::text[], 'Identificação Rápida', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 90, '{"needs_review":false}'::jsonb),
  ('background.gladiator', 'Gladiador', 'Gladiator', 'Gladiador', 'Nas arenas e fossos de combate, você lutou pela sobrevivência e pela aclamação do público, aprendendo a transformar a violência em espetáculo.', 'In arenas and fighting pits, you fought for survival and the crowd''s cheers, turning martial combat into grand theatrical showmanship.', 'En arenas y fosos de combate, luchaste por la supervivencia y el aplauso del público, convirtiendo el combate en un gran espectáculo.', '{}'::text[], '"performance"'::text[], 'Espetáculo Sangrento', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.guard', 'Guarda da Cidade', 'Guard', 'Guardia', 'Você patrulhou portões, muralhas e ruas, fazendo cumprir as leis locais, dispersando tumultos e intimidando malfeitores.', 'You patrolled gates, walls, and streets, enforcing local laws, dispersing brawls, and staring down wrongdoers.', 'Patrullaste puertas, murallas y calles, haciendo cumplir las leyes locales, disolviendo tumultos e intimidando a maleantes.', '{}'::text[], '"intimidation"'::text[], 'Olhar Rápido', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.noble', 'Herdeiro Nobre', 'Noble', 'Noble', 'Criado no privilégio de uma linhagem nobre, você aprendeu política palaciana, genealogia aristocrática e as expectativas do poder.', 'Raised in the privilege of a noble lineage, you learned courtly politics, aristocratic heraldry, and the obligations of power.', 'Criado en el privilegio de un linaje noble, aprendiste política cortesana, heráldica aristocrática y las obligaciones del poder.', '{}'::text[], '"society"'::text[], 'Etiqueta Nobre', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 90, '{"needs_review":false}'::jsonb),
  ('background.sailor', 'Marinheiro', 'Sailor', 'Marinero', 'Você içou velas em mares tempestuosos, manejou cordames e ancoradouros e conhece o ritmo imprevisível das marés.', 'You hoisted sails in stormy seas, handled rigging and anchorages, and know the unpredictable rhythm of the open waters.', 'Izaste velas en mares tempestuosos, manejaste cabos y anclas, y conoces el ritmo impredecible de las aguas abiertas.', '{}'::text[], '"athletics"'::text[], 'Equilíbrio no Convés', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 90, '{"needs_review":false}'::jsonb),
  ('background.merchant', 'Mercador', 'Merchant', 'Mercader', 'Você comprou e vendeu mercadorias em feiras e bazares, avaliando preços justos, lucros e rotas comerciais lucrativas.', 'You bought and sold goods at fairs and bazaars, evaluating fair prices, margins, and profitable trade routes.', 'Compraste y vendiste mercancías en ferias y bazares, evaluando precios justos, márgenes y rutas comerciales rentables.', '{}'::text[], '"diplomacy"'::text[], 'Negociador de Barganhas', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 90, '{"needs_review":false}'::jsonb),
  ('background.miner', 'Mineiro', 'Miner', 'Minero', 'Você escavou túneis profundos com picareta em busca de minérios preciosos, acostumando-se ao confinamento e aos perigos da rocha.', 'You excavated deep tunnels with pickaxe seeking precious ores, getting accustomed to close quarters and underground cave-in hazards.', 'Excavaste túneles profundos con pico en busca de minerales preciosos, acostumbrándote al confinamiento y a los peligros de la roca.', '{}'::text[], '"athletics"'::text[], 'Resistência a Desabamento', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 90, '{"needs_review":false}'::jsonb),
  ('background.nomad', 'Nômade', 'Nomad', 'Nómada', 'Sua tribo ou família viajou constantemente por estepes e desertos, ensinando a você como se orientar pelo sol e pelas estrelas.', 'Your tribe or clan traveled constantly across steppes and deserts, teaching you how to navigate by sun, stars, and weather.', 'Tu tribu o clan viajó constantemente por estepas y desiertos, enseñándote a orientarte por el sol, las estrellas y el clima.', '{}'::text[], '"survival"'::text[], 'Sentido Climático', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 90, '{"needs_review":false}'::jsonb),
  ('background.prisoner', 'Prisioneiro', 'Prisoner', 'Prisionero', 'Trancafiado em masmorras ou colônias penais, você desenvolveu rijeza física e astúcia para resistir ao cárcere e reconquistar a liberdade.', 'Locked in dungeons or penal colonies, you built physical toughness and cunning to survive imprisonment and reclaim freedom.', 'Encerrado en mazmorras o colonias penales, desarrollaste dureza física y astucia para sobrevivir al encierro y recuperar la libertad.', '{}'::text[], '"athletics"'::text[], 'Escapar com Vigor', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 90, '{"needs_review":false}'::jsonb),
  ('background.laborer', 'Trabalhador Braçal', 'Laborer', 'Trabajador manual', 'Você realizou trabalhos pesados na construção de muralhas, estivagem de cais ou corte de lenha, forjando uma constituição musculosa e incansável.', 'You performed hard physical labor building walls, loading docks, or felling timber, forging a muscular and tireless constitution.', 'Realizaste trabajo físico pesado construyendo murallas, cargando muelles o talando árboles, forjando una constitución musculosa e incansable.', '{}'::text[], '"athletics"'::text[], 'Músculo Rústico', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 89, '{"needs_review":false}'::jsonb),
  ('background.barkeeper', 'Taverneiro', 'Barkeeper', 'Tabernero', 'Servindo canecas atrás do balcão, você ouviu fofocas de viajantes, acalmou brigas bêbadas e desenvolveu um excelente senso de diplomacia prática.', 'Pouring ales behind the bar, you listened to traveler gossip, calmed drunken brawls, and honed practical diplomacy.', 'Sirviendo jarras tras la barra, escuchaste cotilleos de viajeros, calmaste peleas de borrachos y afilaste una diplomacia práctica.', '{}'::text[], '"diplomacy"'::text[], 'Ouvido Atento', NULL, 'common', 'remaster', 'Livro do Jogador (Player Core, Remaster)', 88, '{"needs_review":false}'::jsonb),
  ('background.player_core_2.rare.blessed', 'Abençoado', 'Blessed', 'Bendecido', 'Sua bênção divina oferece intuição e proteção em situações difíceis.', 'A divine blessing gives you intuition and protection in difficult situations.', 'Una bendición divina te da intuición y protección en situaciones difíciles.', '{}'::text[], '"religion"'::text[], 'Orientação', 'Saber da Divindade', 'rare', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 52, '{"needs_review":false}'::jsonb),
  ('background.player_core_2.rare.cursed', 'Amaldiçoado', 'Cursed', 'Maldito', 'Uma maldição pessoal ou hereditária ensinou você a resistir a efeitos mágicos nocivos.', 'A personal or inherited curse taught you to resist harmful magical effects.', 'Una maldición personal o hereditaria te enseñó a resistir efectos mágicos dañinos.', '{}'::text[], '"occultism"'::text[], 'Sinal de Proteção', 'Saber de Maldições', 'rare', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 52, '{"needs_review":false}'::jsonb),
  ('background.player_core_2.rare.amnesiac', 'Amnésico', 'Amnesiac', 'Amnésico', 'Seu passado é um mistério, e pistas inesperadas guiam sua descoberta.', 'Your past is a mystery, and unexpected clues guide your discovery.', 'Tu pasado es un misterio, y pistas inesperadas guían tu descubrimiento.', '{}'::text[], '"—"'::text[], '—', '—', 'rare', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 52, '{"needs_review":false}'::jsonb),
  ('background.player_core_2.rare.haunted', 'Assombrado', 'Haunted', 'Embrujado', 'Uma entidade acompanha você desde a infância e influencia sua vida de formas sutis.', 'An entity has followed you since childhood and subtly influences your life.', 'Una entidad te acompaña desde la infancia e influye sutilmente en tu vida.', '{}'::text[], '"occultism"'::text[], '—', 'Saber da Entidade', 'rare', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 52, '{"needs_review":false}'::jsonb),
  ('background.player_core_2.rare.wild_child', 'Criança Selvagem', 'Wild Child', 'Niño salvaje', 'Você cresceu na natureza entre animais, desenvolvendo instintos e uma conexão mística com eles.', 'You grew up in the wild among animals, developing instincts and a mystical connection to them.', 'Creciste en la naturaleza entre animales, desarrollando instintos y una conexión mística con ellos.', '{}'::text[], '"nature"'::text[], 'Forrageador', 'Saber de Animais', 'rare', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 52, '{"needs_review":false}'::jsonb),
  ('background.player_core_2.rare.fae_bound', 'Ligado às Fadas', 'Feybound', 'Vinculado a las hadas', 'Um pacto com as fadas concedeu poderes e um anátema que ainda orienta sua vida.', 'A pact with the fey granted powers and an anathema that still shapes your life.', 'Un pacto con las hadas te concedió poderes y un anatema que aún moldea tu vida.', '{}'::text[], '"nature"'::text[], 'Fortúnio das Fadas', 'Saber de Fadas', 'rare', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 53, '{"needs_review":false}'::jsonb),
  ('background.player_core_2.rare.royalty', 'Realeza', 'Royalty', 'Realeza', 'Você pertence a uma família real e conhece as responsabilidades e privilégios do poder.', 'You belong to a royal family and know the responsibilities and privileges of power.', 'Perteneces a una familia real y conoces las responsabilidades y privilegios del poder.', '{}'::text[], '"society"'::text[], 'Gracejos da Corte', 'Saber da Corte', 'rare', 'remaster', 'Livro do Jogador 2 (Player Core 2, Remaster)', 53, '{"needs_review":false}'::jsonb),
