  ('background.academy_dropout', 'Desistente da Academia', 'Academy Dropout', 'Desertor de la academia', 'Sua passagem interrompida por uma academia mágica ainda molda sua vida.', 'Your interrupted time at a magical academy still shapes your life.', 'Tu paso interrumpido por una academia mágica aún moldea tu vida.', '{}'::text[], '"arcana"'::text[], 'Conhecimento Duvidoso', 'Saber Acadêmico', 'common', 'legacy', 'Segredos da Magia (pré-Remaster)', 29, '{"needs_review":false}'::jsonb),
  ('background.plant_whisperer', 'Encantador de Plantas', 'Plant Whisperer', 'Encantador de plantas', 'Sua afinidade excepcional com plantas beira o sobrenatural.', 'Your exceptional affinity with plants borders on the supernatural.', 'Tu afinidad excepcional con las plantas roza lo sobrenatural.', '{}'::text[], '"nature"'::text[], 'Medicina Natural', 'Saber de Plantas', 'common', 'legacy', 'Segredos da Magia (pré-Remaster)', 29, '{"needs_review":false}'::jsonb),
