  ('background.magical_experiment', 'Experimento Mágico', 'Magical Experiment', 'Experimento mágico', 'Experimentos alteraram permanentemente seu corpo e deixaram uma habilidade incomum.', 'Experiments permanently altered your body and left an unusual ability.', 'Experimentos alteraron tu cuerpo para siempre y dejaron una capacidad inusual.', '{}'::text[], '"occultism"'::text[], 'Alteração Experimental', 'Saber Acadêmico', 'rare', 'legacy', 'Segredos da Magia (pré-Remaster)', 31, '{"needs_review":false}'::jsonb),
  ('background.time_traveler', 'Viajante do Tempo', 'Time Traveler', 'Viajero del tiempo', 'Você chegou de outra época e carrega conhecimentos que não pertencem ao presente.', 'You arrived from another era and carry knowledge that does not belong to the present.', 'Llegaste de otra época y llevas conocimientos que no pertenecen al presente.', '{}'::text[], '"three lore skills"'::text[], 'Dobrar o Tempo', 'Três Saberes do seu tempo', 'rare', 'legacy', 'Segredos da Magia (pré-Remaster)', 31, '{"needs_review":false}'::jsonb),
  ('background.seer_of_the_dead', 'Vidente dos Mortos', 'Seer of the Dead', 'Vidente de los muertos', 'Você percebe e conversa com espíritos que já partiram do mundo dos vivos.', 'You perceive and speak with spirits that have left the world of the living.', 'Percibes y hablas con espíritus que abandonaron el mundo de los vivos.', '{}'::text[], '"religion"'::text[], 'Sentir Espíritos', 'Saber de Mortos-Vivos', 'rare', 'legacy', 'Segredos da Magia (pré-Remaster)', 31, '{"needs_review":false}'::jsonb),
  ('background.guns_gears.rare.technology_dependent', 'Dependente de Tecnologia', 'Technology Dependent', 'Dependiente de la tecnología', 'Seu corpo não tolera mais magia de cura e você depende de dispositivos e engenhosidade.', 'Your body no longer tolerates magical healing, so you rely on devices and ingenuity.', 'Tu cuerpo ya no tolera la curación mágica, así que dependes de dispositivos e ingenio.', '{}'::text[], '"crafting"'::text[], 'Medicina de Batalha', 'medicine', 'rare', 'legacy', 'Pólvora e Engrenagens (pré-Remaster)', 47, '{"needs_review":false}'::jsonb),
  ('background.guns_gears.rare.discarded_duplicate', 'Duplicata Descartada', 'Discarded Duplicate', 'Duplicado descartado', 'Você foi criado para substituir alguém importante e agora explora um mundo que o deixou para trás.', 'You were created to replace someone important and now explore a world that left you behind.', 'Fuiste creado para reemplazar a alguien importante y ahora exploras un mundo que te dejó atrás.', '{}'::text[], '"society"'::text[], '—', 'identity lore', 'rare', 'legacy', 'Pólvora e Engrenagens (pré-Remaster)', 47, '{"needs_review":false}'::jsonb),
  ('background.guns_gears.rare.saved_by_gears', 'Salvo pelas Engrenagens', 'Saved by Gears', 'Salvado por los engranajes', 'Uma prótese mecânica substitui parte do seu corpo e exige manutenção regular.', 'A mechanical prosthesis replaces part of your body and requires regular maintenance.', 'Una prótesis mecánica reemplaza parte de tu cuerpo y requiere mantenimiento regular.', '{}'::text[], '"crafting"'::text[], '—', '—', 'rare', 'legacy', 'Pólvora e Engrenagens (pré-Remaster)', 48, '{"needs_review":false}'::jsonb),
  ('background.guns_gears.rare.mechanical_symbiosis', 'Simbiose Mecânica', 'Mechanical Symbiosis', 'Simbiosis mecánica', 'Uma entidade vive em um objeto maquinal preso ao seu corpo e às suas decisões.', 'An entity lives within a mechanical object attached to your body and choices.', 'Una entidad vive en un objeto mecánico unido a tu cuerpo y tus decisiones.', '{}'::text[], '"arcana"'::text[], '—', 'entity lore', 'rare', 'legacy', 'Pólvora e Engrenagens (pré-Remaster)', 48, '{"needs_review":false}'::jsonb),
  ('background.guns_gears.rare.desired_life', 'Vida Desejada', 'Desired Life', 'Vida deseada', 'Você foi um constructo ou boneco inanimado que ganhou vida por causa de um desejo profundo.', 'You were once an inanimate construct or doll who gained life through a profound wish.', 'Antes eras un constructo o muñeco inanimado que cobró vida por un deseo profundo.', '{}'::text[], '"diplomacy"'::text[], '—', '—', 'rare', 'legacy', 'Pólvora e Engrenagens (pré-Remaster)', 48, '{"needs_review":false}'::jsonb),
